export const Route = createFileRoute("/admin")({
  beforeLoad: async ({ location }) => {
    const session = await getAdminSession();
    if (!session && location.pathname !== "/admin/login") {
      throw redirect({ to: "/admin/login" });
    }
  },
  component: AdminRouteLayout,
});

function AdminRouteLayout() {
  const location = useLocation();
  const [session, setSession] = useState<AdminSession | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    void getAdminSession().then((currentSession) => {
      if (!active) return;
      setSession(currentSession);
      setLoading(false);
    });
    return () => {
      active = false;
    };
  }, []);

  if (location.pathname === "/admin/login") return <Outlet />;

  if (loading) {
    return <main className="flex min-h-screen items-center justify-center bg-background text-sm text-muted-foreground">Carregando painel...</main>;
  }

  if (!session) return null;

  return <AdminDashboard session={session} />;
}

function AdminDashboard({ session }: { session: AdminSession }) {
  const navigate = useNavigate();
  const [section, setSection] = useState("Visão geral");
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    "Visão geral": true,
    Catálogo: true,
    Pedidos: true,
    "Site / Aparência": true,
  });
  const [productArea, setProductArea] = useState<"Produtos" | "Categorias" | "Variantes" | "Promoções">("Produtos");
  const [inventoryArea, setInventoryArea] = useState<"Estoque" | "Movimentações" | "Reservas" | "Alertas">("Estoque");
  const [alertOrderId, setAlertOrderId] = useState<string | null>(null);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);

  const sectionDescription: Record<string, string> = {
    "Visão geral": "Acompanhe vendas, pedidos, envios e devoluções em um único lugar.",
    Alertas: "Priorize problemas reais de estoque, reservas e pagamentos.",
    Produtos: "Gerencie o catálogo sem misturar dados operacionais.",
    Estoque: "Controle variantes, movimentações, reservas e limites de alerta.",
    Pedidos: "Consulte pedidos, clientes, pagamentos e status de atendimento.",
    "Site / Aparência": "Edite a experiência publicada na Home e na loja.",
  };

  const sectionTitle = section === "Site / Aparência" ? "EDITOR DA HOME" : section;
  const breadcrumb = section === "Site / Aparência" ? ["Admin", "EDITOR DA HOME"] : ["Admin", section];
  const headerDescription = sectionDescription[section] || "Administre esta área com segurança a partir dos dados reais da loja.";

  function handleSectionChange(nextSection: string) {
    setSection(nextSection);
    setMobileSidebarOpen(false);
    if (nextSection === "Produtos") setProductArea("Produtos");
  }

  function toggleGroup(group: string) {
    setOpenGroups((current) => ({ ...current, [group]: !current[group] }));
  }

  async function handleSignOut() {
    await signOutAdmin();
    await navigate({ to: "/admin/login", replace: true });
  }

  const navigationGroups = [
    { label: "Visão geral", icon: LayoutDashboard, items: [{ label: "Visão geral", icon: LayoutDashboard }, { label: "Alertas", icon: AlertTriangle }] },
    { label: "Catálogo", icon: Boxes, items: [{ label: "Produtos", icon: Package }, { label: "Estoque", icon: Boxes }] },
    { label: "Pedidos", icon: ShoppingCart, items: [{ label: "Pedidos", icon: ClipboardList }, { label: "Envios e Rastreamento", icon: Truck }, { label: "Devoluções", icon: ShieldCheck }, { label: "Financeiro", icon: CircleDollarSign }] },
    { label: "Clientes", icon: Users, items: [{ label: "Clientes", icon: Users }] },
    { label: "Fornecedores", icon: Store, items: [{ label: "Fornecedores", icon: Store }] },
    { label: "Site e Aparência", icon: Palette, items: [{ label: "Editor da Home", icon: Eye }] },
    { label: "Configurações", icon: Settings, items: [{ label: "Análises", icon: BarChart3 }, { label: "Configurações", icon: Cog }] },
  ];

  return <div className="admin-shell min-h-screen bg-background text-foreground">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-72 flex-col bg-slate-950 text-slate-300 transition-transform duration-200 md:translate-x-0 ${mobileSidebarOpen ? "translate-x-0" : "-translate-x-full"}`} aria-label="Navegação administrativa">
      <div className="flex h-24 items-center border-b border-border px-6"><Link to="/admin" className="flex flex-col text-sm font-medium tracking-[0.18em] text-foreground"><span>LEH_CLOSETT</span><span className="mt-1 text-xs tracking-[0.28em] text-primary">ADMIN STUDIO</span></Link></div>
      <div className="flex-1 overflow-y-auto px-4 py-6"><p className="mb-4 px-3 text-[10px] font-semibold uppercase tracking-[0.24em] text-slate-500">Central de controle</p><nav className="space-y-3">
        {navigationGroups.map((group) => { const GroupIcon = group.icon; return <section key={group.label}><button type="button" onClick={() => toggleGroup(group.label)} aria-expanded={openGroups[group.label] ?? false} className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500 hover:text-white"><span className="flex items-center gap-2"><GroupIcon size={14} />{group.label}</span>{openGroups[group.label] ? <ChevronDown size={14} /> : <ChevronRight size={14} />}</button>{openGroups[group.label] && <div className="mt-1 space-y-1">{group.items.map((item) => { const ItemIcon = item.icon; const active = section === item.label || (section === "Site / Aparência" && group.label === "Site e Aparência"); return <button key={item.label} type="button" onClick={() => { if (group.label === "Site e Aparência") { setSection("Site / Aparência"); setMobileSidebarOpen(false); } else handleSectionChange(item.label); }} className={`flex w-full items-center gap-3 rounded-lg border-l-2 px-3 py-2 text-left text-sm transition ${active ? "border-cyan-400 bg-slate-800 text-white" : "border-transparent text-slate-400 hover:bg-slate-900 hover:text-white"}`}><ItemIcon size={16} />{item.label}</button>; })}</div>}</section>; })}
      </nav></div><div className="border-t border-slate-800 p-4"><p className="truncate px-2 text-xs text-slate-500">{session.email}</p><button type="button" onClick={handleSignOut} className="mt-3 w-full rounded-lg border border-slate-700 px-3 py-2 text-sm text-slate-300 transition hover:border-cyan-400 hover:text-white">Sair do painel</button></div>
    </aside>
    {mobileSidebarOpen && <button type="button" aria-label="Fechar menu" onClick={() => setMobileSidebarOpen(false)} className="fixed inset-0 z-30 bg-slate-950/60 md:hidden" />}
    <div className="min-h-screen md:pl-72">
      <header className="sticky top-0 z-20 border-b border-slate-200 bg-white/95 backdrop-blur"><div className="flex min-h-20 flex-wrap items-center justify-between gap-4 px-5 py-4 md:px-10"><div className="flex items-center gap-4"><button type="button" aria-label="Abrir menu" onClick={() => setMobileSidebarOpen(true)} className="rounded-lg border border-slate-200 p-2 text-slate-600 hover:border-cyan-500 hover:text-cyan-600 md:hidden"><Menu size={20} /></button><div><p className="text-xs font-semibold uppercase tracking-[0.2em] text-cyan-600">Administração</p><p className="text-sm text-slate-500">Operação LEH_CLOSETT</p></div></div><div className="flex items-center gap-2 sm:gap-3"><label className="relative hidden md:block"><span className="sr-only">Buscar no Admin</span><Search size={16} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" /><input disabled aria-label="Busca do Admin indisponível" placeholder="Buscar produtos, pedidos, clientes..." className="h-10 w-64 cursor-not-allowed rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-sm text-slate-500 opacity-80" title="A busca global ainda não está disponível" /></label><button type="button" aria-label="Notificações" className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:border-cyan-500 hover:text-cyan-600"><Bell size={18} /></button><div className="hidden border-l border-slate-200 pl-3 text-right sm:block"><p className="max-w-40 truncate text-sm font-medium text-slate-800">{session.email}</p><p className="text-xs text-slate-500">Administrador</p></div><button type="button" onClick={() => void handleSignOut()} aria-label="Sair do painel" className="rounded-lg border border-slate-200 p-2 text-slate-500 hover:border-red-300 hover:text-red-600"><LogOut size={18} /></button></div></div></header>
      <main key={section} className="min-w-0 px-5 py-10 md:px-12 md:py-14"><div className="mb-8 border-b border-slate-200 pb-6"><nav aria-label="Breadcrumb" className="mb-3 flex flex-wrap items-center gap-2 text-xs text-slate-400">{breadcrumb.map((item, index) => <span key={`${item}-${index}`} className={index === breadcrumb.length - 1 ? "font-medium text-cyan-600" : ""}>{index > 0 && <span className="mr-2 text-slate-300">/</span>}{item}</span>)}</nav><div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-end"><div><h1 className="text-4xl font-normal tracking-tight text-foreground md:text-5xl">{sectionTitle}</h1><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500">{headerDescription}</p></div></div></div>{section === "Visão geral" ? <OverviewDashboard /> : section === "Site / Aparência" ? <UnifiedHomeEditor /> : section === "Produtos" ? <ProductsArea area={productArea} onAreaChange={(a) => setProductArea(a as typeof productArea)} /> : section === "Estoque" ? <InventoryArea area={inventoryArea} onAreaChange={setInventoryArea} /> : section === "Alertas" ? <AdminAlertsPage onOpenArea={(area) => { setSection("Estoque"); setInventoryArea(area); }} onOpenOrder={(orderId) => { setSection("Pedidos"); setAlertOrderId(orderId); }} /> : section === "Pedidos" ? <OrdersManagerList initialOrderId={alertOrderId} /> : section === "Envios e Rastreamento" ? <ShipmentsManager /> : section === "Fornecedores" ? <SuppliersManager /> : <section className="mt-8 rounded-xl border border-slate-200 bg-white p-8 shadow-sm"><p className="text-slate-500">Selecione uma função no menu para visualizar e gerenciar esta área.</p></section>}</main>
    </div>
  </div>;
}

function OverviewDashboardLegacy() {
  const [period, setPeriod] = useState<"day" | "week" | "month">("week");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [now, setNow] = useState(new Date());
  const [orders, setOrders] = useState<any[]>([]);
  const [shipments, setShipments] = useState<any[]>([]);
  const [refunds, setRefunds] = useState<any[]>([]);

  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { void (async () => {
    if (!supabase) { setError("Supabase não está configurado."); setLoading(false); return; }
    try {
      setLoading(true); setError("");
      const [orderResult, shipmentResult, refundResult] = await Promise.all([
        supabase.from("orders").select("id,total,created_at,status,payment_status,order_items(*)"),
        supabase.from("shipments").select("id,status,order_id"),
        supabase.from("refunds").select("amount,status,created_at")
      ]);
      if (orderResult.error) throw orderResult.error;
      if (shipmentResult.error) throw shipmentResult.error;
      if (refundResult.error) throw refundResult.error;
      setOrders(orderResult.data ?? []); setShipments(shipmentResult.data ?? []); setRefunds(refundResult.data ?? []);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os indicadores."); }
    finally { setLoading(false); }
  })(); }, []);

  const start = new Date();
  if (period === "day") start.setHours(0, 0, 0, 0);
  if (period === "week") { start.setDate(start.getDate() - 6); start.setHours(0, 0, 0, 0); }
  if (period === "month") { start.setDate(1); start.setHours(0, 0, 0, 0); }
  const paid = (order: any) => ["paid", "approved", "pago", "approved_payment"].includes(String(order.payment_status || "").toLowerCase());
  const periodOrders = orders.filter((order) => paid(order) && new Date(order.created_at) >= start);
  const sales = periodOrders.reduce((sum, order) => sum + Number(order.total || 0), 0);
  const totalSales = orders.filter(paid).reduce((sum, order) => sum + Number(order.total || 0), 0);
  const pending = orders.filter((order) => ["preparing", "processing", "paid", "pago"].includes(String(order.status || "").toLowerCase())).length;
  const inTransit = shipments.filter((shipment) => ["shipped", "in_transit", "em_transit", "em trânsito"].includes(String(shipment.status || "").toLowerCase())).length;
  const delivered = shipments.filter((shipment) => ["delivered", "entregue"].includes(String(shipment.status || "").toLowerCase())).length;
  const refundsTotal = refunds.filter((refund) => !refund.status || !["cancelled", "rejected"].includes(String(refund.status).toLowerCase())).reduce((sum, refund) => sum + Number(refund.amount || 0), 0);
  const buckets = period === "day" ? 6 : period === "week" ? 7 : 5;
  const chart = Array.from({ length: buckets }, (_, index) => { const date = new Date(start); if (period === "day") date.setHours(index * 4); else if (period === "week") date.setDate(start.getDate() + index); else date.setDate(1 + index * Math.max(1, Math.floor((new Date().getDate() - 1) / Math.max(1, buckets - 1)))); const next = new Date(date); if (period === "day") next.setHours(date.getHours() + 4); else if (period === "week") next.setDate(date.getDate() + 1); else next.setDate(date.getDate() + 7); return { label: period === "day" ? `${date.getHours()}h` : date.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }), value: periodOrders.filter((order) => { const created = new Date(order.created_at); return created >= date && created < next; }).reduce((sum, order) => sum + Number(order.total || 0), 0) }; });
  const max = Math.max(...chart.map((item) => item.value), 1);
  const card = (label: string, value: string) => <article className="rounded-xl border border-border bg-card p-5"><p className="text-xs uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-3 text-2xl font-semibold tabular-nums">{loading ? "—" : value}</p></article>;
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Atualizado em {now.toLocaleString("pt-BR")}</p><div className="flex rounded-lg border border-border p-1">{(["day", "week", "month"] as const).map((item) => <button key={item} type="button" onClick={() => setPeriod(item)} className={`rounded-md px-3 py-1.5 text-sm ${period === item ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{item === "day" ? "Dia" : item === "week" ? "Semana" : "Mês"}</button>)}</div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{card("Vendas no período", `R$ ${sales.toFixed(2)}`)}{card("Vendas totais", `R$ ${totalSales.toFixed(2)}`)}{card("Aguardando postagem", String(pending))}{card("Em trânsito", String(inTransit))}{card("Entregues", String(delivered))}{card("Total de devoluções", `R$ ${refundsTotal.toFixed(2)}`)}</div><section className="rounded-xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold">Vendas</h2><p className="text-sm text-muted-foreground">Pedidos pagos no período selecionado</p></div><strong className="text-xl">R$ {sales.toFixed(2)}</strong></div><div className="mt-6 flex h-48 items-end gap-2 border-b border-border">{chart.map((item) => <div key={item.label} className="flex flex-1 flex-col items-center gap-2"><div title={`R$ ${item.value.toFixed(2)}`} className="w-full rounded-t-md bg-primary transition-all" style={{ height: `${Math.max(item.value / max * 100, item.value ? 4 : 1)}%` }} /><span className="text-[11px] text-muted-foreground">{item.label}</span></div>)}</div></section></div>;
}

function OverviewDashboard() {
  const [orders, setOrders] = useState<any[]>([]);
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => { void (async () => {
    try {
      setLoading(true);
      const [orderRows, productRows] = await Promise.all([listAdminOrders(), listAdminProducts()]);
      setOrders(orderRows); setProducts(productRows);
    } catch (err) { setError(describeSupabaseError(err, "Não foi possível carregar a visão geral.")); }
    finally { setLoading(false); }
  })(); }, []);

  const today = new Date(); today.setHours(0, 0, 0, 0);
  const todayOrders = orders.filter((order) => new Date(order.created_at).getTime() >= today.getTime());
  const paid = (order: any) => ["paid", "approved", "pago", "approved_payment", "confirmed"].includes(String(order.payment_status || "").toLowerCase());
  const todaySales = todayOrders.filter(paid).reduce((sum, order) => sum + Number(order.total || 0), 0);
  const customers = new Set(orders.map((order) => order.user_id || order.customer_email || order.shipping_address?.email).filter(Boolean));
  const lowStock = products.flatMap((product) => product.product_variants).filter((variant) => variant.stock_quantity <= 5).length;
  const money = (value: number) => `R$ ${value.toFixed(2).replace(".", ",")}`;
  const card = (label: string, value: string) => <article className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><p className="text-xs font-semibold uppercase tracking-wider text-slate-500">{label}</p><p className="mt-3 text-2xl font-semibold text-slate-950">{loading ? "—" : value}</p></article>;
  return <div className="mt-8 space-y-6">
    {error && <p className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>}
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{card("Pedidos hoje", String(todayOrders.length))}{card("Vendas hoje", money(todaySales))}{card("Clientes ativos", String(customers.size))}{card("Estoque baixo", String(lowStock))}</div>
    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-slate-950">Vendas recentes</h2><p className="text-sm text-slate-500">Valores dos pedidos pagos nos últimos registros.</p></div><span className="text-xs text-slate-500">Dados reais</span></div><div className="mt-6 flex h-40 items-end gap-2 border-b border-slate-200">{[...orders].filter(paid).slice(0, 7).reverse().map((order) => { const max = Math.max(...orders.filter(paid).map((item) => Number(item.total || 0)), 1); return <div key={order.id} className="flex flex-1 flex-col items-center gap-2"><div title={money(Number(order.total || 0))} className="w-full rounded-t bg-cyan-600" style={{ height: `${Math.max(Number(order.total || 0) / max * 100, 5)}%` }} /><span className="text-[10px] text-slate-400">{new Date(order.created_at).toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" })}</span></div>; })}</div></section>
    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-slate-950">Pedidos recentes</h2><p className="text-sm text-slate-500">Acompanhe os últimos pedidos registrados.</p></div></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><tr><th className="p-3">Pedido</th><th className="p-3">Cliente</th><th className="p-3">Status</th><th className="p-3">Valor</th></tr></thead><tbody>{loading ? <tr><td colSpan={4} className="p-6 text-center text-slate-500">Carregando pedidos reais...</td></tr> : orders.slice(0, 5).map((order) => <tr key={order.id} className="border-b border-slate-100 last:border-0"><td className="p-3 font-medium">{order.order_number || order.id}</td><td className="p-3 text-slate-600">{order.customer_name || order.customer_email || order.shipping_address?.full_name || "Cliente não identificado"}</td><td className="p-3 text-slate-600">{order.status || "—"}</td><td className="p-3">{money(Number(order.total || 0))}</td></tr>)}{!loading && orders.length === 0 && <tr><td colSpan={4} className="p-6 text-center text-slate-500">Nenhum pedido real encontrado.</td></tr>}</tbody></table></div></section>
  </div>;
}

type HomeControlCard = { name: string; description: string; icon: typeof Eye; area: string; getStats: (data: HomeControlData) => { summary: string; status: string } };
type HomeControlData = { banners: Banner[]; appearance: Record<string, unknown> };

function HomeControlPanel({ onManage }: { onManage: (area: string) => void }) {
  const [data, setData] = useState<HomeControlData>({ banners: [], appearance: {} });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => { void (async () => { try { if (!supabase) throw new Error("Supabase não configurado."); const [bannerRows, settings] = await Promise.all([listAdminBanners(), supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle()]); if (settings.error) throw settings.error; const appearance = settings.data?.appearance && typeof settings.data.appearance === "object" ? settings.data.appearance as Record<string, unknown> : {}; setData({ banners: bannerRows, appearance }); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os conteúdos reais da Home."); } finally { setLoading(false); } })(); }, []);
  const count = (value: unknown) => Array.isArray(value) ? value.length : 0;
  const active = (value: unknown) => Array.isArray(value) ? value.filter((item) => typeof item === "object" && item !== null && Boolean((item as Record<string, unknown>).active ?? true)).length : 0;
  const cards: HomeControlCard[] = [
    { name: "Hero principal", description: "Controle título, frase e chamadas do destaque principal.", icon: Eye, area: "Textos", getStats: ({ appearance }) => ({ summary: appearance.texts ? "Configuração cadastrada" : "Não há conteúdo cadastrado", status: appearance.texts ? "Configurado" : "Pendente" }) },
    { name: "Banners", description: "Imagens e chamadas exibidas no topo da Home.", icon: Image, area: "Banners", getStats: ({ banners }) => ({ summary: `${banners.length} banner${banners.length === 1 ? "" : "s"} · ${banners.filter((item) => item.active).length} ativos`, status: banners.length ? "Publicado" : "Não há conteúdo cadastrado" }) },
    { name: "Frases e chamadas", description: "Textos promocionais e chamadas exibidos na Home.", icon: FileText, area: "Textos", getStats: ({ appearance }) => ({ summary: appearance.texts ? "Textos cadastrados" : "Não há conteúdo cadastrado", status: appearance.texts ? "Configurado" : "Pendente" }) },
    { name: "Seções", description: "Blocos de conteúdo organizados na página inicial.", icon: LayoutDashboard, area: "Seções", getStats: ({ appearance }) => ({ summary: `${count(appearance.sections)} seção(ões) · ${active(appearance.sections)} ativas`, status: count(appearance.sections) ? "Publicado" : "Não há conteúdo cadastrado" }) },
    { name: "Cards", description: "Cards promocionais e informativos da Home.", icon: Boxes, area: "Cards", getStats: ({ appearance }) => ({ summary: `${count(appearance.cards)} card(s) · ${active(appearance.cards)} ativos`, status: count(appearance.cards) ? "Publicado" : "Não há conteúdo cadastrado" }) },
    { name: "Benefícios", description: "Benefícios e argumentos apresentados ao cliente.", icon: ShieldCheck, area: "Benefícios", getStats: ({ appearance }) => ({ summary: `${count(appearance.benefits)} benefício(s) · ${active(appearance.benefits)} ativos`, status: count(appearance.benefits) ? "Publicado" : "Não há conteúdo cadastrado" }) },
    { name: "Campanhas", description: "Campanhas e comunicações especiais da Home.", icon: CircleDollarSign, area: "Campanhas", getStats: ({ appearance }) => ({ summary: `${count(appearance.campaigns)} campanha(s) · ${active(appearance.campaigns)} ativas`, status: count(appearance.campaigns) ? "Publicado" : "Não há conteúdo cadastrado" }) },
  ];
  return <section className="space-y-5" aria-labelledby="home-control-title"><div><h2 id="home-control-title" className="text-xl font-semibold">Controle da Home</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Administre cada tipo de conteúdo separadamente, sem misturar formulários.</p></div>{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{loading ? <div className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Carregando conteúdo real da Home...</div> : <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{cards.map((card) => { const Icon = card.icon; const stats = card.getStats(data); return <article key={card.name} className="flex min-h-52 flex-col rounded-xl border border-border bg-card p-5 shadow-sm transition hover:border-primary/50 hover:shadow-md"><div className="flex items-center justify-between gap-3"><span className="rounded-lg bg-muted p-2 text-primary"><Icon size={19} aria-hidden="true" /></span><span className="text-xs text-muted-foreground">{stats.status}</span></div><h3 className="mt-5 text-base font-semibold">{card.name}</h3><p className="mt-2 flex-1 text-sm leading-relaxed text-muted-foreground">{card.description}</p><div className="mt-4 border-t border-border pt-3 text-xs text-muted-foreground">{stats.summary}</div><button type="button" onClick={() => onManage(card.area)} className="mt-4 self-start rounded-lg bg-primary px-3 py-2 text-sm font-medium text-primary-foreground transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">Gerenciar</button></article>; })}</div>}</section>;
}

function AppearanceArea() {
  return <section className="admin-appearance mt-8 rounded-xl border border-dashed border-border bg-card p-10 text-center">
    <h2 className="text-2xl font-semibold tracking-tight">Editor do site limpo</h2>
    <p className="mx-auto mt-3 max-w-xl text-sm leading-relaxed text-muted-foreground">As funções de edição e aparência foram removidas temporariamente. Esta página será refeita em uma próxima etapa.</p>
  </section>;
}

type HomeEditorBlock = { id: string; number: string; name: string; description: string; active: boolean; divider?: boolean };
type BannerStyle = { font: string; size: number; titleColor: string; textColor: string; positionX: number; positionY: number };
const defaultBannerStyle: BannerStyle = { font: "Montserrat", size: 50, titleColor: "#ffffff", textColor: "#ffffff", positionX: 50, positionY: 50 };
const bannerFonts = ["Montserrat", "Playfair Display", "Syncopate", "Arial", "Georgia"];

const initialHomeEditorBlocks: HomeEditorBlock[] = [
  { id: "hero", number: "01", name: "Hero / Banners", description: "Imagem, vídeo, frase, título e configurações de transição do destaque.", active: true },
  { id: "divider-1", number: "02", name: "Divisória", description: "Separação visual entre o destaque e os produtos em evidência.", active: true, divider: true },
  { id: "featured", number: "04", name: "Produtos em destaque", description: "Produtos escolhidos para aparecer primeiro na vitrine.", active: true },
  { id: "divider-2", number: "05", name: "Divisória", description: "Separação visual entre destaques e promoções.", active: true, divider: true },
  { id: "promotions", number: "06", name: "Produtos em promoção", description: "Ofertas e produtos com preço promocional.", active: true },
  { id: "divider-3", number: "07", name: "Divisória", description: "Separação visual antes das categorias.", active: true, divider: true },
  { id: "categories", number: "08", name: "Categorias", description: "Categorias disponíveis para orientar a descoberta de produtos.", active: true },
  { id: "divider-4", number: "09", name: "Divisória", description: "Separação visual antes do banner institucional.", active: true, divider: true },
  { id: "banner-text", number: "10", name: "Banner + frase", description: "Imagem de apoio e frase institucional da Home.", active: true },
  { id: "divider-5", number: "11", name: "Divisória", description: "Separação visual antes dos canais de atendimento.", active: true, divider: true },
  { id: "social", number: "12", name: "Redes sociais / Contato / Suporte", description: "Canais de contato, redes sociais e suporte ao cliente.", active: true },
  { id: "divider-6", number: "13", name: "Divisória", description: "Separação visual antes do encerramento da Home.", active: true, divider: true },
  { id: "footer", number: "13", name: "Rodapé", description: "Informações finais, links institucionais e direitos autorais.", active: true },
];

function UnifiedHomeEditor() {
  const [blocks, setBlocks] = useState<HomeEditorBlock[]>(initialHomeEditorBlocks);
  const [headerOpen, setHeaderOpen] = useState(false);
  const [heroOpen, setHeroOpen] = useState(true);
  const [headerSettings, setHeaderSettings] = useState({ logoUrl: "", menuVisible: true, menuItems: ["Início", "Coleções", "Categorias", "Contato"], iconsVisible: true });
  const [banners, setBanners] = useState<Banner[]>([]);
  const [bannerStyles, setBannerStyles] = useState<Record<string, BannerStyle>>({});
  const [bannerLoading, setBannerLoading] = useState(false);
  const [bannerError, setBannerError] = useState("");
  const [draggedBanner, setDraggedBanner] = useState<string | null>(null);
  const [bannerForm, setBannerForm] = useState({ image_url: "", title: "", text: "", link_url: "", sort_order: 0, active: true });
  const [editingBanner, setEditingBanner] = useState<string | undefined>();
  const [savingBanner, setSavingBanner] = useState(false);

  function styleFor(id?: string) { return id ? { ...defaultBannerStyle, ...(bannerStyles[id] ?? {}) } : defaultBannerStyle; }
  async function persistBannerStyles(next: Record<string, BannerStyle>) {
    setBannerStyles(next);
    if (!supabase) return;
    const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle();
    const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {};
    await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, heroBannerStyles: next } });
  }

  useEffect(() => { void (async () => { try { setBannerLoading(true); const [rows, settings] = await Promise.all([listAdminBanners(), supabase?.from("store_settings").select("appearance").eq("id", "default").maybeSingle()]); setBanners(rows); const appearance = settings?.data?.appearance && typeof settings.data.appearance === "object" ? settings.data.appearance as Record<string, unknown> : {}; const storedStyles = appearance.heroBannerStyles && typeof appearance.heroBannerStyles === "object" ? appearance.heroBannerStyles as Record<string, BannerStyle> : {}; setBannerStyles(storedStyles); const header = appearance.header && typeof appearance.header === "object" ? appearance.header as Record<string, unknown> : {}; setHeaderSettings({ logoUrl: String(header.logoUrl ?? ""), menuVisible: Boolean(header.menuVisible ?? true), menuItems: Array.isArray(header.menuItems) ? header.menuItems.map(String) : ["Início", "Coleções", "Categorias", "Contato"], iconsVisible: Boolean(header.iconsVisible ?? true) }); } catch (err) { setBannerError(err instanceof Error ? err.message : "Não foi possível carregar o editor."); } finally { setBannerLoading(false); } })(); }, []);

  async function saveHeader(next: typeof headerSettings) { setHeaderSettings(next); if (!supabase) return; const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {}; await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, header: next } }); }
  async function saveBanner(event: React.FormEvent) { event.preventDefault(); try { setSavingBanner(true); await saveAdminBanner({ id: editingBanner, ...bannerForm, sort_order: banners.length }); setBannerForm({ image_url: "", title: "", text: "", link_url: "", sort_order: 0, active: true }); setEditingBanner(undefined); setBanners(await listAdminBanners()); } catch (err) { setBannerError(err instanceof Error ? err.message : "Não foi possível salvar o banner."); } finally { setSavingBanner(false); } }
  async function duplicateBanner(banner: Banner) { await saveAdminBanner({ image_url: banner.image_url, title: `${banner.title || "Banner"} (cópia)`, text: banner.text, link_url: banner.link_url, sort_order: banners.length, active: banner.active }); setBanners(await listAdminBanners()); }
  async function reorderBanner(id: string, targetId: string) { const next = [...banners]; const from = next.findIndex((item) => item.id === id); const to = next.findIndex((item) => item.id === targetId); if (from < 0 || to < 0) return; const [item] = next.splice(from, 1); next.splice(to, 0, item); try { await Promise.all(next.map((banner, index) => saveAdminBanner({ ...banner, sort_order: index }))); setBanners(await listAdminBanners()); } catch (err) { setBannerError(err instanceof Error ? err.message : "Não foi possível alterar a ordem."); } }
  function bannerType(banner: Banner) { return banner.image_url?.match(/\.(mp4|webm|ogg)(\?|$)/i) ? "Vídeo" : "Imagem"; }
  const [selectedId, setSelectedId] = useState("hero");
  const [blocksLoading, setBlocksLoading] = useState(true);
  const [blocksMessage, setBlocksMessage] = useState("");

  useEffect(() => { void (async () => {
    if (!supabase) { setBlocksLoading(false); return; }
    const result = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle();
    if (result.error) { setBlocksMessage(result.error.message); setBlocksLoading(false); return; }
    const appearance = result.data?.appearance && typeof result.data.appearance === "object" ? result.data.appearance as Record<string, unknown> : {};
    if (Array.isArray(appearance.home_blocks)) setBlocks(appearance.home_blocks as HomeEditorBlock[]);
    setBlocksLoading(false);
  })(); }, []);

  async function persistBlocks(next: HomeEditorBlock[]) {
    setBlocks(next);
    if (!supabase) return;
    const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle();
    if (current.error) throw current.error;
    const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {};
    const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, home_blocks: next } });
    if (result.error) throw result.error;
  }

  function move(id: string, direction: -1 | 1) {
    const index = blocks.findIndex((block) => block.id === id);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= blocks.length) return;
    const next = [...blocks];
    [next[index], next[target]] = [next[target], next[index]];
    void persistBlocks(next.map((block, position) => ({ ...block, number: String(position + 1).padStart(2, "0") }))).catch((error) => setBlocksMessage(error instanceof Error ? error.message : "Não foi possível salvar a ordem."));
  }

  function addDivider() {
    const next = [...blocks, { id: `divider-${Date.now()}`, number: String(blocks.length + 1).padStart(2, "0"), name: "Divisória", description: "Nova separação visual para organizar a hierarquia da Home.", active: true, divider: true }];
    void persistBlocks(next).catch((error) => setBlocksMessage(error instanceof Error ? error.message : "Não foi possível salvar a divisória."));
  }

  return <div className="space-y-6">
    <div className="flex flex-col gap-2 border-b border-border pb-6">
      <p className="text-xs font-semibold uppercase tracking-[0.2em] text-primary">Site e Aparência · funções administrativas</p>
      <h2 className="text-3xl font-semibold tracking-tight text-foreground">EDITOR DA HOME</h2>
      <p className="max-w-2xl text-sm leading-relaxed text-muted-foreground">Organize a Home pública e edite os blocos de cabeçalho e banners diretamente nesta tela.</p>
    </div>
    {blocksMessage && <p role="alert" className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{blocksMessage}</p>}
    <div className="grid min-w-0 gap-8 lg:grid-cols-[minmax(0,1fr)_minmax(20rem,0.72fr)] lg:items-start">
      <section aria-labelledby="home-blocks-title" className="min-w-0 space-y-4">
        <div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-primary">Etapa 01 · Organização</p><h3 id="home-blocks-title" className="text-xl font-semibold text-foreground">Estrutura da Home</h3><p className="mt-1 text-sm text-muted-foreground">Cada bloco permanece na mesma tela e pode ser ativado ou reorganizado.</p></div><button type="button" onClick={addDivider} className="rounded-lg border border-primary px-3 py-2 text-sm font-medium text-primary transition hover:bg-primary hover:text-primary-foreground">+ Adicionar divisória</button></div>
        <div className="space-y-3">{blocksLoading ? <div className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Carregando estrutura salva...</div> : blocks.map((block, index) => <article key={block.id} className={`min-w-0 rounded-xl border bg-card p-4 transition ${selectedId === block.id ? "border-primary shadow-sm" : "border-border"}`}>
          <div className="flex min-w-0 items-start gap-3"><span className="shrink-0 font-mono text-sm font-semibold text-primary">{block.number}</span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h4 className="text-base font-semibold">{block.name}</h4>{block.divider && <span className="rounded-full border border-border px-2 py-0.5 text-[10px] uppercase tracking-wider text-muted-foreground">Estrutural</span>}</div><p className="mt-1 text-sm leading-relaxed text-muted-foreground">{block.description}</p></div><button type="button" role="switch" aria-checked={block.active} aria-label={`${block.active ? "Desativar" : "Ativar"} ${block.name}`} onClick={() => { const next = blocks.map((item) => item.id === block.id ? { ...item, active: !item.active } : item); void persistBlocks(next).catch((error) => setBlocksMessage(error instanceof Error ? error.message : "Não foi possível salvar o status.")); }} className={`relative h-6 w-11 shrink-0 rounded-full border transition ${block.active ? "border-primary bg-primary" : "border-border bg-muted"}`}><span className={`absolute top-0.5 h-4 w-4 rounded-full bg-primary-foreground transition ${block.active ? "right-0.5" : "left-0.5"}`} /></button></div>
          <div className="mt-4 flex flex-wrap items-center gap-2 border-t border-border pt-3"><button type="button" onClick={() => { setSelectedId(block.id); if (block.id === "header") setHeaderOpen((value) => !value); if (block.id === "hero" || block.id === "banner-text") setHeroOpen((value) => !value); }} aria-pressed={selectedId === block.id} className="rounded-md bg-foreground px-3 py-1.5 text-xs font-semibold text-background transition hover:bg-primary hover:text-primary-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{selectedId === block.id ? "Editando" : "Editar"}</button><button type="button" disabled={index === 0} onClick={() => move(block.id, -1)} className="rounded-md border border-border px-3 py-1.5 text-xs disabled:opacity-40">Subir</button><button type="button" disabled={index === blocks.length - 1} onClick={() => move(block.id, 1)} className="rounded-md border border-border px-3 py-1.5 text-xs disabled:opacity-40">Descer</button><span className="ml-auto text-xs text-muted-foreground">{block.active ? "Ativo na Home" : "Oculto na Home"}</span></div>
          {block.id === "header" && headerOpen && <div className="mt-4 space-y-4 rounded-lg border border-primary/30 bg-background p-4"><div className="flex items-center justify-between"><h5 className="font-medium">Opções do cabeçalho</h5><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={headerSettings.iconsVisible} onChange={(e) => void saveHeader({ ...headerSettings, iconsVisible: e.target.checked })} />Mostrar ícones</label></div><AdminFileUpload kind="image" folder="home/header" onUploaded={({ url }) => void saveHeader({ ...headerSettings, logoUrl: url })} onError={setBannerError} />{headerSettings.logoUrl && <img src={headerSettings.logoUrl} alt="Logo selecionada para a Home" className="h-12 w-auto object-contain" />}<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={headerSettings.menuVisible} onChange={(e) => void saveHeader({ ...headerSettings, menuVisible: e.target.checked })} />Mostrar menu</label><label className="block text-sm">Itens do menu<input value={headerSettings.menuItems.join(" | ")} onChange={(e) => void saveHeader({ ...headerSettings, menuItems: e.target.value.split("|").map((item) => item.trim()).filter(Boolean) })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label></div>}
          {(block.id === "hero" || block.id === "banner-text") && heroOpen && <div className="mt-4 space-y-4 rounded-lg border border-primary/30 bg-background p-4"><div className="flex items-center justify-between"><div><h5 className="font-medium">{block.id === "banner-text" ? "Banner institucional e frase" : "Gerenciamento de banners"}</h5><p className="text-xs text-muted-foreground">{block.id === "banner-text" ? "Adicione ou edite a imagem e a frase desta etapa da Home." : "Tudo permanece dentro de Hero / Banners."}</p></div><button type="button" onClick={() => setBannerForm({ image_url: "", title: "", text: "", link_url: "", sort_order: banners.length, active: true })} className="rounded-md bg-primary px-3 py-2 text-xs text-primary-foreground">+ Adicionar banner</button></div><form onSubmit={saveBanner} className="grid gap-3 rounded-md border border-border p-3"><AdminFileUpload kind="all" folder="home/banners" onUploaded={({ url }) => setBannerForm((current) => ({ ...current, image_url: url }))} onError={setBannerError} /><input aria-label="Título do banner" placeholder="Título do banner" value={bannerForm.title} onChange={(e) => setBannerForm({ ...bannerForm, title: e.target.value })} className="h-10 rounded-lg border border-input bg-background px-3" /><label className="text-sm">Frase<textarea aria-label="Frase do banner" value={bannerForm.text} onChange={(e) => setBannerForm({ ...bannerForm, text: e.target.value })} rows={2} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label>{editingBanner && <div className="grid gap-3 sm:grid-cols-2"><label className="text-sm">Fonte<select value={styleFor(editingBanner).font} onChange={(e) => void persistBannerStyles({ ...bannerStyles, [editingBanner]: { ...styleFor(editingBanner), font: e.target.value } })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3">{bannerFonts.map((font) => <option key={font} style={{ fontFamily: font }}>{font}</option>)}</select><span style={{ fontFamily: styleFor(editingBanner).font }} className="mt-1 block text-lg">Amostra da fonte</span></label><label className="text-sm">Tamanho: {styleFor(editingBanner).size}%<input type="range" min="25" max="100" value={styleFor(editingBanner).size} onChange={(e) => void persistBannerStyles({ ...bannerStyles, [editingBanner]: { ...styleFor(editingBanner), size: Number(e.target.value) } })} className="mt-3 w-full" /><span className="flex justify-between text-xs text-muted-foreground"><span>Pequeno</span><span>Grande</span></span></label><label className="flex items-center gap-2 text-sm">Cor do título<input type="color" value={styleFor(editingBanner).titleColor} onChange={(e) => void persistBannerStyles({ ...bannerStyles, [editingBanner]: { ...styleFor(editingBanner), titleColor: e.target.value } })} /></label><label className="flex items-center gap-2 text-sm">Cor da frase<input type="color" value={styleFor(editingBanner).textColor} onChange={(e) => void persistBannerStyles({ ...bannerStyles, [editingBanner]: { ...styleFor(editingBanner), textColor: e.target.value } })} /></label><div className="sm:col-span-2"><p className="text-sm">Posição do texto</p><div className="mt-2 grid grid-cols-3 gap-1">{[[25,25,"↖"],[50,25,"↑"],[75,25,"↗"],[25,50,"←"],[50,50,"•"],[75,50,"→"],[25,75,"↙"],[50,75,"↓"],[75,75,"↘"]].map(([x,y,label]) => <button type="button" key={`${x}-${y}`} onClick={() => void persistBannerStyles({ ...bannerStyles, [editingBanner]: { ...styleFor(editingBanner), positionX: Number(x), positionY: Number(y) } })} className="rounded border border-border p-2 text-sm hover:bg-muted">{label}</button>)}</div></div></div>}<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={bannerForm.active} onChange={(e) => setBannerForm({ ...bannerForm, active: e.target.checked })} />Banner ativo</label><button disabled={savingBanner} className="justify-self-start rounded-md bg-primary px-3 py-2 text-xs text-primary-foreground">{savingBanner ? "Salvando..." : editingBanner ? "Atualizar banner" : "Salvar banner"}</button></form>{bannerError && <p className="text-sm text-destructive">{bannerError}</p>}{bannerLoading ? <p className="text-sm text-muted-foreground">Carregando banners...</p> : banners.length === 0 ? <p className="rounded-md border border-dashed border-border p-4 text-sm text-muted-foreground">Nenhum banner cadastrado.</p> : <div className="grid gap-3 sm:grid-cols-2">{banners.map((banner) => <article key={banner.id} draggable onDragStart={() => setDraggedBanner(banner.id)} onDragOver={(e) => e.preventDefault()} onDrop={() => { if (draggedBanner) void reorderBanner(draggedBanner, banner.id); }} className="overflow-hidden rounded-lg border border-border bg-card"><div className="flex aspect-[16/7] items-center justify-center bg-muted">{banner.image_url ? (bannerType(banner) === "Vídeo" ? <video src={banner.image_url} muted controls className="h-full w-full object-cover" aria-label={`Prévia de ${banner.title || "banner"}`} /> : <img src={banner.image_url} alt={banner.title || "Miniatura do banner"} className="h-full w-full object-cover" />) : <Image aria-hidden="true" className="text-muted-foreground" />}</div><div className="space-y-2 p-3"><div className="flex justify-between gap-2"><h6 className="truncate font-medium">{banner.title || "Banner sem título"}</h6><span className="text-xs text-muted-foreground">{bannerType(banner)}</span></div><p className="text-xs text-muted-foreground">{banner.active ? "Ativo" : "Inativo"}</p><div className="flex flex-wrap gap-2 text-xs"><button type="button" onClick={() => void saveAdminBanner({ ...banner, active: !banner.active }).then(() => listAdminBanners().then(setBanners))} className="text-primary">{banner.active ? "Desativar" : "Ativar"}</button><button type="button" onClick={() => { setEditingBanner(banner.id); setBannerForm({ image_url: banner.image_url || "", title: banner.title || "", text: banner.text || "", link_url: banner.link_url || "", sort_order: banner.sort_order, active: banner.active }); setEditingBanner(banner.id); }} className="text-primary">Editar</button><button type="button" onClick={() => void duplicateBanner(banner)} className="text-primary">Duplicar</button><button type="button" onClick={() => void deleteAdminBanner(banner.id).then(() => listAdminBanners().then(setBanners))} className="text-destructive">Excluir</button></div></div></article>)}</div>}</div>}
        </article>)}</div>
      </section>
      <aside className="hidden" aria-hidden="true"><div className="overflow-hidden rounded-xl border border-border bg-card"><div className="border-b border-border p-5"><p className="text-xs font-semibold uppercase tracking-[0.18em] text-primary">Prévia da Home</p><h3 id="home-preview-title" className="mt-1 text-xl font-semibold">PRÉVIA DA HOME</h3><p className="mt-1 text-sm text-muted-foreground">Ordem pública dos blocos ativos.</p></div><div className="max-h-[calc(100vh-15rem)] space-y-2 overflow-y-auto p-4">{blocks.filter((block) => block.active).map((block) => <div key={block.id} onClick={() => setSelectedId(block.id)} className={`cursor-pointer rounded-lg border p-3 transition ${selectedId === block.id ? "border-primary bg-primary/10" : "border-border bg-background hover:border-primary/50"}`}><div className="flex items-center gap-2"><span className="font-mono text-[10px] text-primary">{block.number}</span><span className="text-sm font-medium">{block.name}</span></div>{block.id === "header" ? <div className="mt-3 flex items-center justify-between gap-2 border-t border-border pt-3"><span className="font-semibold">{headerSettings.logoUrl ? <img src={headerSettings.logoUrl} alt="Logo da prévia" className="h-6 w-auto object-contain" /> : "LEH_CLOSETT"}</span>{headerSettings.menuVisible && <span className="truncate text-[10px] text-muted-foreground">{headerSettings.menuItems.join(" · ")}</span>}{headerSettings.iconsVisible && <span aria-hidden="true">♡</span>}</div> : block.id === "hero" ? (() => { const selectedBanner = banners.find((banner) => banner.id === editingBanner) ?? banners.find((banner) => banner.active); const previewBanner = selectedBanner && editingBanner === selectedBanner.id ? { ...selectedBanner, ...bannerForm } : selectedBanner; const previewStyle = styleFor(previewBanner?.id); const isVideo = previewBanner ? bannerType(previewBanner) === "Vídeo" : false; return <div className="mt-3 overflow-hidden rounded-md border border-border">{previewBanner?.image_url ? <div className="relative aspect-[16/7] w-full overflow-hidden bg-muted">{isVideo ? <video key={previewBanner.image_url} src={previewBanner.image_url} autoPlay muted loop playsInline className="absolute inset-0 h-full w-full object-cover" aria-label={`Prévia de ${previewBanner.title || "banner"}`} /> : <img src={previewBanner.image_url} alt={previewBanner.title || "Banner da prévia"} className="absolute inset-0 h-full w-full object-cover" />}<div className="absolute inset-0" style={{ padding: "1rem" }}><div className="absolute max-w-[85%]" style={{ top: `${previewStyle.positionY}%`, left: `${previewStyle.positionX}%`, transform: "translate(-50%, -50%)", textAlign: previewStyle.positionX < 40 ? "left" : previewStyle.positionX > 60 ? "right" : "center" }}><h4 style={{ color: previewStyle.titleColor, fontFamily: previewStyle.font, fontSize: `${Math.max(1, previewStyle.size / 28)}rem`, lineHeight: 1.05 }} className="font-semibold">{previewBanner.title || "Título do banner"}</h4><p style={{ color: previewStyle.textColor, fontFamily: previewStyle.font, fontSize: `${Math.max(0.75, previewStyle.size / 55)}rem` }} className="mt-1">{previewBanner.text || "Frase do banner"}</p></div></div></div> : <div className="p-4 text-xs text-muted-foreground">Nenhum banner selecionado</div>}</div>; })() : block.divider ? <div className="mt-2 border-t border-border" /> : <p className="mt-1 text-xs text-muted-foreground">Conteúdo visível na Home pública</p>}</div>)}</div></div></aside>
    </div>
    <section className="space-y-6 border-t border-border pt-8" aria-labelledby="home-content-editor-title"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-primary">Conteúdo conectado à Home</p><h3 id="home-content-editor-title" className="mt-1 text-2xl font-semibold">Produtos, categorias e apresentação</h3><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Escolha produtos reais, defina a ordem das seções e edite contato, redes sociais e rodapé sem sair desta tela.</p></div><HomeSectionsEditor /><div className="grid gap-6 lg:grid-cols-2"><StorePresentationEditor mode="social" /><StorePresentationEditor mode="footer" /></div></section>
  </div>;
}
function UnifiedAppearanceEditor() { return <div className="space-y-8"><ThemeColorsEditor /><section className="border-t border-border pt-8"><StorePresentationEditor /></section></div>; }

type HomeSection = { id: string; title: string; type: "Categoria" | "Destaques" | "Mais vendidos" | "Produtos" | "Personalizada"; active: boolean; sort_order: number; category_id?: string; product_ids?: string[]; product_sort?: "recent" | "price_desc" | "price_asc" }; 

function HomeSectionsEditor() {
  const blank: Omit<HomeSection, "id"> = { title: "", type: "Destaques", active: true, sort_order: 0, category_id: "", product_ids: [], product_sort: "recent" }; 
  const [rows, setRows] = useState<HomeSection[]>([]); const [form, setForm] = useState(blank); const [editing, setEditing] = useState<string | undefined>(); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  const [categories, setCategories] = useState<AdminCategory[]>([]); const [products, setProducts] = useState<AdminProduct[]>([]);
  async function load() { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const value = Array.isArray(appearance.sections) ? appearance.sections : []; setRows(value.map((item, index) => ({ id: String((item as Record<string, unknown>).id ?? crypto.randomUUID()), title: String((item as Record<string, unknown>).title ?? ""), type: ((item as Record<string, unknown>).type ?? "Destaques") as HomeSection["type"], active: Boolean((item as Record<string, unknown>).active ?? true), sort_order: Number((item as Record<string, unknown>).sort_order ?? index), category_id: String((item as Record<string, unknown>).category_id ?? ""), product_ids: Array.isArray((item as Record<string, unknown>).product_ids) ? (item as Record<string, unknown>).product_ids as string[] : [], product_sort: ((item as Record<string, unknown>).product_sort ?? "recent") as HomeSection["product_sort"] })).sort((a, b) => a.sort_order - b.sort_order)); setLoading(false); }
  useEffect(() => { void load(); void (async () => { try { const [categoryRows, productRows] = await Promise.all([listAdminCategories(), listAdminProducts()]); setCategories(categoryRows.filter((item) => item.active)); setProducts(productRows.filter((item) => item.active)); } catch (err) { setMessage(describeSupabaseError(err, "Não foi possível carregar categorias e produtos.")); } })(); }, []);
  async function persist(next: HomeSection[]) { if (!supabase) return; const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (current.error) throw current.error; const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, sections: next } }); if (result.error) throw result.error; setRows(next); }
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!form.title.trim()) return; try { setSaving(true); setMessage(""); const next = editing ? rows.map((row) => row.id === editing ? { id: editing, ...form } : row) : [...rows, { id: crypto.randomUUID(), ...form, sort_order: rows.length }]; await persist(next); setForm(blank); setEditing(undefined); setMessage("Seções salvas no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  async function remove(id: string) { if (!window.confirm("Excluir esta seção da Home?")) return; try { await persist(rows.filter((row) => row.id !== id).map((row, index) => ({ ...row, sort_order: index }))); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível excluir."); } }
  async function move(id: string, direction: -1 | 1) { const index = rows.findIndex((row) => row.id === id); const target = index + direction; if (target < 0 || target >= rows.length) return; const next = [...rows]; [next[index], next[target]] = [next[target], next[index]]; try { await persist(next.map((row, order) => ({ ...row, sort_order: order }))); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível reordenar."); } }
  return <div className="space-y-6"><form onSubmit={submit} className="grid gap-4 rounded-xl border border-border bg-card p-5 md:grid-cols-2"><label className="text-sm">Título personalizado<input required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Tipo<select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value as HomeSection["type"], category_id: "", product_ids: [] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3">{["Categoria", "Destaques", "Mais vendidos", "Produtos", "Personalizada"].map((type) => <option key={type}>{type}</option>)}</select></label>{form.type === "Categoria" && <label className="text-sm">Categoria<select value={form.category_id} onChange={(e) => setForm({ ...form, category_id: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">Selecione uma categoria</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>}{(form.type === "Destaques" || form.type === "Produtos" || form.type === "Personalizada") && <div className="space-y-3 md:col-span-2"><div><p className="text-sm">Produtos selecionados <span className="text-muted-foreground">({(form.product_ids ?? []).length}{form.type === "Destaques" ? "/10" : ""})</span></p><p className="mt-1 text-xs text-muted-foreground">A Home exibirá os produtos exatamente nesta ordem.</p>{form.type === "Personalizada" && <p className="mt-1 text-xs text-primary">Divisão personalizada da Home.</p>}</div><div className="space-y-2">{(form.product_ids ?? []).length === 0 ? <p className="rounded-lg border border-dashed border-border p-4 text-sm text-muted-foreground">Nenhum produto selecionado.</p> : (form.product_ids ?? []).map((productId, index) => { const product = products.find((item) => item.id === productId); return product ? <div key={product.id} className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2"><span className="truncate text-sm">{index + 1}. {product.name}</span><div className="flex shrink-0 gap-2 text-xs"><button type="button" disabled={index === 0} onClick={() => { const ids = [...(form.product_ids ?? [])]; [ids[index - 1], ids[index]] = [ids[index], ids[index - 1]]; setForm({ ...form, product_ids: ids }); }} className="text-primary disabled:opacity-40">Subir</button><button type="button" disabled={index === (form.product_ids ?? []).length - 1} onClick={() => { const ids = [...(form.product_ids ?? [])]; [ids[index], ids[index + 1]] = [ids[index + 1], ids[index]]; setForm({ ...form, product_ids: ids }); }} className="text-primary disabled:opacity-40">Descer</button><button type="button" onClick={() => setForm({ ...form, product_ids: (form.product_ids ?? []).filter((id) => id !== product.id) })} className="text-destructive">Remover</button></div></div> : null; })}</div><label className="block text-sm">Adicionar produto<select value="" disabled={form.type === "Destaques" && (form.product_ids ?? []).length >= 10} onChange={(e) => { const id = e.target.value; if (id && !(form.product_ids ?? []).includes(id) && (form.type !== "Destaques" || (form.product_ids ?? []).length < 10)) setForm({ ...form, product_ids: [...(form.product_ids ?? []), id] }); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">{form.type === "Destaques" && (form.product_ids ?? []).length >= 10 ? "Limite de 10 produtos atingido" : "Selecione um produto"}</option>{products.filter((product) => !(form.product_ids ?? []).includes(product.id)).map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>{form.type === "Produtos" && <label className="block text-sm">Ordenação<select value={form.product_sort ?? "recent"} onChange={(e) => setForm({ ...form, product_sort: e.target.value as HomeSection["product_sort"] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="recent">Mais recentes</option><option value="price_desc">Maior preço</option><option value="price_asc">Menor preço</option></select></label>}</div>}<label className="flex items-center gap-2 pb-2 text-sm"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Ativa</label><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editing ? "Atualizar" : "Criar seção"}</button></form>{message && <p className="rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}{loading ? <p className="text-sm text-muted-foreground">Carregando seções...</p> : rows.length === 0 ? <p className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Nenhuma seção administrada. A Home não exibirá blocos de conteúdo.</p> : <div className="space-y-3">{rows.map((row, index) => <article key={row.id} className="flex flex-wrap items-center justify-between gap-4 rounded-xl border border-border bg-card p-4"><div><h3 className="font-medium">{row.title}</h3><p className="text-sm text-muted-foreground">{row.type} · {row.active ? "Ativa" : "Inativa"} · {row.product_ids?.length ?? 0} produtos · posição {index + 1}</p></div><div className="flex gap-3 text-sm"><button type="button" disabled={index === 0} onClick={() => void move(row.id, -1)} className="text-primary disabled:opacity-40">Subir</button><button type="button" disabled={index === rows.length - 1} onClick={() => void move(row.id, 1)} className="text-primary disabled:opacity-40">Descer</button><button type="button" onClick={() => { setEditing(row.id); setForm({ title: row.title, type: row.type, active: row.active, sort_order: row.sort_order, category_id: row.category_id ?? "", product_ids: row.product_ids ?? [], product_sort: row.product_sort ?? "recent" }); }} className="text-primary">Editar</button><button type="button" onClick={() => void remove(row.id)} className="text-destructive">Excluir</button></div></article>)}</div>}</div>;
}

type ThemeColors = { primary: string; secondary: string; accent: string; background: string; secondaryBackground: string; text: string; secondaryText: string; button: string; buttonText: string };
type ThemeTypography = { bodyFont: string; headingFont: string; baseSize: string; headingWeight: string; bodyWeight: string; headingSize: string; subtitleSize: string };
const defaultThemeColors: ThemeColors = { primary: "#e11d48", secondary: "#be123c", accent: "#f59e0b", background: "#fff1f2", secondaryBackground: "#ffe4e6", text: "#1f1720", secondaryText: "#6b5360", button: "#e11d48", buttonText: "#ffffff" };
const defaultThemeTypography: ThemeTypography = { bodyFont: "Montserrat", headingFont: "Playfair Display", baseSize: "16px", headingWeight: "600", bodyWeight: "400", headingSize: "32px", subtitleSize: "18px" };
const availableFonts = ["Montserrat", "Playfair Display", "Syncopate"];

function ThemeColorsEditor() {
  const [colors, setColors] = useState<ThemeColors>(defaultThemeColors); const [typography, setTypography] = useState<ThemeTypography>(defaultThemeTypography); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [applying, setApplying] = useState(false); const [message, setMessage] = useState(""); const [status, setStatus] = useState<"saved" | "dirty" | "applying" | "applied" | "error">("saved");
  const fields: Array<[keyof ThemeColors, string]> = [["primary", "Cor principal"], ["secondary", "Cor secundária"], ["accent", "Cor de destaque"], ["background", "Fundo principal"], ["secondaryBackground", "Fundo secundário"], ["text", "Cor de texto"], ["secondaryText", "Cor de texto secundário"], ["button", "Cor de botões"], ["buttonText", "Cor de texto dos botões"]];
  useEffect(() => { void (async () => { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const stored = appearance.colors && typeof appearance.colors === "object" ? appearance.colors as Partial<ThemeColors> : {}; const storedTypography = appearance.typography && typeof appearance.typography === "object" ? appearance.typography as Partial<ThemeTypography> : {}; setColors({ ...defaultThemeColors, ...stored }); setTypography({ ...defaultThemeTypography, ...storedTypography }); setLoading(false); })(); }, []);
  async function save(next: ThemeColors, nextTypography: ThemeTypography = typography) { if (!supabase) return; const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (current.error) throw current.error; const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, colors: next, typography: nextTypography } }); if (result.error) throw result.error; }
  async function submit(event: React.FormEvent) { event.preventDefault(); try { setSaving(true); setStatus("dirty"); setMessage("Salvando alterações..."); await save(colors, typography); setStatus("saved"); setMessage("Alterações salvas."); } catch (err) { setStatus("error"); setMessage(err instanceof Error ? err.message : "Não foi possível salvar as cores."); } finally { setSaving(false); } }
  async function applyTheme() { try { setApplying(true); setStatus("applying"); setMessage("Aplicando tema..."); await save(colors, typography); setStatus("applied"); setMessage("Tema aplicado com sucesso."); } catch (err) { setStatus("error"); setMessage(err instanceof Error ? err.message : "Não foi possível aplicar o tema."); } finally { setApplying(false); } }
  function restore() { if (window.confirm("Restaurar o padrão visual e substituir as cores atuais?")) { setColors(defaultThemeColors); setTypography(defaultThemeTypography); setStatus("dirty"); setMessage("Padrão restaurado na prévia. Salve para persistir."); } }
  return <section className="grid gap-6 lg:grid-cols-[1.1fr_0.9fr]"><form onSubmit={submit} className="rounded-xl border border-border bg-card p-5"><h2 className="text-xl font-semibold">PALETA DO SITE</h2><p className="mt-1 text-sm text-muted-foreground">Escolha cada cor visualmente. As alterações só são persistidas ao salvar.</p>{loading ? <p className="mt-6 text-sm text-muted-foreground">Carregando cores...</p> : <><div className="mt-5 grid gap-3 sm:grid-cols-2">{fields.map(([key, label]) => <label key={key} className="flex items-center gap-3 rounded-lg border border-border bg-background p-3 text-sm"><input aria-label={label} type="color" value={colors[key]} onChange={(event) => { setColors({ ...colors, [key]: event.target.value }); setStatus("dirty"); setMessage("Alterações não salvas."); }} className="h-11 w-14 cursor-pointer rounded border-0 bg-transparent p-0" /><span className="font-medium">{label}</span></label>)}</div><div className="mt-5 flex flex-wrap gap-3"><button type="submit" disabled={saving || loading} className="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar alterações"}</button><button type="button" onClick={restore} className="rounded-lg border border-border px-4 py-2 text-sm font-medium hover:bg-muted">Restaurar padrão</button></div><p className="mt-3 text-xs text-muted-foreground">{status === "dirty" ? "Alterações não salvas" : status === "saved" ? "Alterações salvas" : status === "applying" ? "Aplicação em andamento" : status === "applied" ? "Aplicação concluída" : "Erro na operação"}</p></>}</form><section className="rounded-xl border border-border bg-card p-5"><h2 className="text-xl font-semibold">TIPOGRAFIA DO SITE</h2><p className="mt-1 text-sm text-muted-foreground">Fontes disponíveis no projeto, sem URLs externas.</p><div className="mt-4 grid gap-4 sm:grid-cols-2">{([["bodyFont", "Fonte principal"], ["headingFont", "Fonte dos títulos"]] as const).map(([key, label]) => <label key={key} className="text-sm">{label}<select value={typography[key]} onChange={(event) => { setTypography({ ...typography, [key]: event.target.value }); setStatus("dirty"); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3">{availableFonts.map((font) => <option key={font}>{font}</option>)}</select></label>)}{([["baseSize", "Tamanho base do texto"], ["headingSize", "Tamanho dos títulos principais"], ["subtitleSize", "Tamanho dos subtítulos"]] as const).map(([key, label]) => <label key={key} className="text-sm">{label}<select value={typography[key]} onChange={(event) => { setTypography({ ...typography, [key]: event.target.value }); setStatus("dirty"); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option>14px</option><option>16px</option><option>18px</option><option>20px</option><option>24px</option><option>32px</option><option>40px</option></select></label>)}{([["headingWeight", "Peso dos títulos"], ["bodyWeight", "Peso dos textos"]] as const).map(([key, label]) => <label key={key} className="text-sm">{label}<select value={typography[key]} onChange={(event) => { setTypography({ ...typography, [key]: event.target.value }); setStatus("dirty"); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="400">Regular</option><option value="500">Médio</option><option value="600">Semibold</option><option value="700">Bold</option></select></label>)}</div></section><div className="rounded-xl border border-border bg-card p-5" aria-label="Prévia do tema"><h2 className="text-xl font-semibold">PRÉVIA DO TEMA</h2><div style={{ backgroundColor: colors.background, color: colors.text, fontFamily: typography.bodyFont, fontSize: typography.baseSize, fontWeight: typography.bodyWeight }} className="mt-5 overflow-hidden rounded-xl border p-4"><header style={{ backgroundColor: colors.secondaryBackground, borderColor: colors.secondary }} className="flex items-center justify-between border-b px-4 py-3"><strong style={{ color: colors.primary }}>LEH_CLOSETT</strong><button type="button" style={{ backgroundColor: colors.button, color: colors.buttonText }} className="rounded-md px-3 py-2 text-xs font-medium">Menu</button></header><div className="mt-4 space-y-4"><div style={{ backgroundColor: colors.secondary, color: colors.buttonText }} className="rounded-lg p-5"><p className="text-xs uppercase tracking-wider">Banner demonstrativo</p><h3 style={{ fontFamily: typography.headingFont, fontSize: typography.headingSize, fontWeight: typography.headingWeight }} className="mt-2 leading-tight">Uma experiência coerente</h3><button type="button" style={{ backgroundColor: colors.button, color: colors.buttonText }} className="mt-4 rounded-md px-4 py-2 text-sm font-medium">Botão principal</button></div><div><h3 style={{ color: colors.primary, fontFamily: typography.headingFont, fontSize: typography.subtitleSize, fontWeight: typography.headingWeight }} className="leading-tight">Título de seção</h3><p style={{ color: colors.secondaryText, fontWeight: typography.bodyWeight }} className="mt-1">Texto de demonstração visual do tema.</p></div><div style={{ backgroundColor: colors.secondaryBackground, borderColor: colors.secondary }} className="rounded-lg border p-4"><span className="font-medium">Card e selo <b style={{ backgroundColor: colors.accent, color: colors.text }} className="ml-2 rounded-full px-2 py-1 text-xs">Destaque</b></span><input aria-label="Campo de entrada da prévia" placeholder="Campo de entrada" className="mt-3 h-9 w-full rounded-md border bg-background px-3 text-sm" /><button type="button" style={{ backgroundColor: colors.secondary, color: colors.buttonText }} className="mt-3 rounded-md px-4 py-2 text-sm">Botão secundário</button></div></div></div><div className="mt-5 rounded-lg border border-primary/30 bg-primary/5 p-4"><p className="text-sm font-semibold">APLICAR TEMA AO SITE</p><p className="mt-1 text-xs text-muted-foreground">Usa as cores salvas em store_settings.appearance.colors no sistema público.</p><button type="button" onClick={() => void applyTheme()} disabled={applying || saving} className="mt-3 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50">{applying ? "Aplicando..." : "Aplicar alterações"}</button></div></div>{message && <p className="lg:col-span-2 rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}</section>;
}

type StorePresentation = { storeName: string; storeDescription: string; instagram: string; linktree: string; whatsapp: string; whatsappFloating: string; footer: string };
type TextAppearance = { title: string; phrase: string; titleFont: string; titleSize: string; titleColor: string; phraseFont: string; phraseSize: string; phraseColor: string; textWidth: string; textFormat: "normal" | "uppercase" | "italic"; heroEyebrow: string; primaryCta: string; primaryCtaUrl: string; secondaryCta: string; secondaryCtaUrl: string; sectionEyebrow: string; shippingHighlight: string; shippingText: string };
const defaultTextAppearance: TextAppearance = { title: "", phrase: "", titleFont: "Playfair Display", titleSize: "clamp(3rem, 8vw, 7rem)", titleColor: "var(--foreground)", phraseFont: "Montserrat", phraseSize: "1rem", phraseColor: "var(--foreground)", textWidth: "32rem", textFormat: "normal", heroEyebrow: "", primaryCta: "", primaryCtaUrl: "", secondaryCta: "", secondaryCtaUrl: "", sectionEyebrow: "", shippingHighlight: "", shippingText: "" };

const defaultStorePresentation: StorePresentation = { storeName: "LEH_CLOSETT GLOW", storeDescription: "Moda para iluminar quem você é.", instagram: "", linktree: "", whatsapp: "", whatsappFloating: "", footer: "© 2025 LEH_CLOSETT GLOW. Todos os direitos reservados." };

function StorePresentationEditor({ mode = "all" }: { mode?: "all" | "footer" | "social" }) {
  const [form, setForm] = useState<StorePresentation>(defaultStorePresentation); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { void (async () => { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; setForm({ ...defaultStorePresentation, ...(appearance.presentation as Partial<StorePresentation> | undefined) }); setLoading(false); })(); }, []);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!supabase) return; try { setSaving(true); const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) throw error; const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, presentation: form } }); if (result.error) throw result.error; setMessage("Apresentação salva no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  const fields: Array<[keyof StorePresentation, string, string]> = mode === "footer" ? [["footer", "Texto do rodapé", ""]] : mode === "social" ? [["instagram", "Instagram", "https://instagram.com/"], ["linktree", "Linktree", "https://linktr.ee/"] , ["whatsapp", "WhatsApp", "https://wa.me/"] , ["whatsappFloating", "Número do botão flutuante", "5511999999999"]] : [["storeName", "Nome da loja", ""], ["storeDescription", "Descrição da loja", ""], ["instagram", "Instagram", "https://instagram.com/"], ["linktree", "Linktree", "https://linktr.ee/"], ["whatsapp", "WhatsApp", "https://wa.me/"], ["whatsappFloating", "Número do botão flutuante", "5511999999999"], ["footer", "Texto do rodapé", ""]];
  return <section className="rounded-xl border border-border bg-card p-5"><h2 className="text-xl font-semibold">Apresentação da loja</h2><p className="mt-1 text-sm text-muted-foreground">Esses dados são salvos na configuração real da loja.</p><form onSubmit={submit} className="mt-5 grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando configurações...</p> : <>{fields.map(([key, label, placeholder]) => <label key={key} className="text-sm">{label}{key === "storeDescription" || key === "footer" ? <textarea value={form[key]} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /> : <input value={form[key]} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" />}</label>)}<div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar apresentação"}</button></div></>}</form>{message && <p className="mt-4 rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}</section>;
}

function HomeImagesEditor() {
  type GalleryImage = { id: string; path?: string; url: string; label: string; source: string; createdAt?: string };
  const bucket = "product-images";
  const [images, setImages] = useState<GalleryImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);

  async function loadImages() {
    if (!supabase) { setError("Supabase não está configurado."); setLoading(false); return; }
    try {
      setLoading(true); setError("");
      const [banners, products, storage] = await Promise.all([
        listAdminBanners(),
        listAdminProducts(),
        supabase.storage.from(bucket).list("admin/gallery", { limit: 100, sortBy: { column: "created_at", order: "desc" } }),
      ]);
      if (storage.error) throw storage.error;
      const referenced = [
        ...banners.filter((item) => item.image_url).map((item) => ({ id: `banner-${item.id}`, url: item.image_url!, label: item.title || "Banner da Home", source: "Banners" })),
        ...products.flatMap((product) => product.product_images.map((item) => ({ id: `product-${item.id}`, url: item.image_url, label: product.name, source: "Produtos" }))),
      ];
      const stored = (storage.data ?? []).filter((item) => item.id).map((item) => {
        const path = `admin/gallery/${item.name}`;
        const { data } = supabase!.storage.from(bucket).getPublicUrl(path);
        return { id: `storage-${path}`, path, url: data.publicUrl, label: item.name, source: "Galeria", createdAt: item.created_at ?? undefined };
      });
      const unique = new Map<string, GalleryImage>();
      [...stored, ...referenced].forEach((item) => unique.set(item.url, item));
      setImages([...unique.values()]);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar a galeria."); }
    finally { setLoading(false); }
  }

  useEffect(() => { void loadImages(); }, [refreshKey]);

  const isReferenced = (url: string) => images.some((item) => item.url === url && item.source !== "Galeria");
  async function removeImage(image: GalleryImage) {
    if (!image.path) { setError("Esta imagem é gerenciada pela área de origem e não pode ser excluída daqui."); return; }
    if (isReferenced(image.url)) { setError("Esta imagem está vinculada a um conteúdo existente. Remova a referência na área de origem antes de excluir."); return; }
    if (!window.confirm(`Excluir a imagem ${image.label}?`)) return;
    if (!supabase) return;
    const { error: removeError } = await supabase.storage.from(bucket).remove([image.path]);
    if (removeError) { setError(removeError.message); return; }
    setMessage("Imagem excluída com sucesso."); setRefreshKey((value) => value + 1);
  }

  return <section className="space-y-5 rounded-xl border border-border bg-card p-5">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><h2 className="text-xl font-semibold">Galeria de imagens</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Imagens reais disponíveis no Storage e já utilizadas pela loja. URLs não são exibidas como conteúdo principal.</p></div><span className="inline-flex items-center gap-2 text-sm text-muted-foreground"><Upload size={16} /> Envio direto</span></div>
    <AdminFileUpload bucket={bucket} folder="admin/gallery" kind="image" onUploaded={({ file }) => { setMessage(`${file.name} enviado para a galeria.`); setRefreshKey((value) => value + 1); }} onError={setError} />
    {error && <p role="alert" className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    {message && <p role="status" className="rounded-lg border border-primary/30 bg-primary/5 p-3 text-sm text-primary">{message}</p>}
    {loading ? <p className="rounded-lg border border-border p-8 text-center text-sm text-muted-foreground">Carregando galeria...</p> : images.length === 0 ? <div className="rounded-lg border border-dashed border-border p-8 text-center"><Image className="mx-auto text-muted-foreground" size={28} /><h3 className="mt-3 font-medium">Nenhuma imagem encontrada</h3><p className="mt-1 text-sm text-muted-foreground">Envie uma imagem para disponibilizá-la na galeria.</p></div> : <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{images.map((image) => <article key={image.id} className="overflow-hidden rounded-lg border border-border bg-background"><img src={image.url} alt={image.label} className="aspect-[4/3] w-full object-cover" /><div className="space-y-3 p-3"><div><p className="truncate text-sm font-medium" title={image.label}>{image.label}</p><p className="text-xs text-muted-foreground">{image.createdAt ? new Date(image.createdAt).toLocaleDateString("pt-BR") : `Origem: ${image.source}`}</p></div><div className="flex flex-wrap gap-2"><button type="button" className="rounded-md border border-border px-3 py-2 text-xs font-medium hover:bg-muted">Usar/Editar</button>{image.path && <button type="button" onClick={() => void removeImage(image)} className="inline-flex items-center gap-1 rounded-md border border-destructive/40 px-3 py-2 text-xs font-medium text-destructive hover:bg-destructive/10"><Trash2 size={14} />Excluir</button>}</div></div></article>)}</div>}
  </section>;
}

function HomeVideosEditor() {
  type VideoFile = { path: string; url: string; name: string; createdAt?: string; size?: number };
  const bucket = "product-images";
  const [videos, setVideos] = useState<VideoFile[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [message, setMessage] = useState("");
  async function load() { if (!supabase) { setError("Supabase não está configurado."); setLoading(false); return; } try { setLoading(true); const result = await supabase.storage.from(bucket).list("admin/videos", { limit: 100, sortBy: { column: "created_at", order: "desc" } }); if (result.error) throw result.error; setVideos((result.data ?? []).filter((item) => item.id).map((item) => { const path = `admin/videos/${item.name}`; return { path, name: item.name, createdAt: item.created_at ?? undefined, size: item.metadata?.size, url: supabase!.storage.from(bucket).getPublicUrl(path).data.publicUrl }; })); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os vídeos."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  async function remove(video: VideoFile) { if (!window.confirm(`Excluir o vídeo ${video.name}?`)) return; if (!supabase) return; const result = await supabase.storage.from(bucket).remove([video.path]); if (result.error) { setError(result.error.message); return; } setMessage("Vídeo excluído com sucesso."); await load(); }
  const size = (value?: number) => value ? `${(value / (1024 * 1024)).toFixed(1)} MB` : "Tamanho não informado";
  return <section className="space-y-5 rounded-xl border border-border bg-card p-5"><div><h2 className="text-xl font-semibold">Galeria de vídeos</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Vídeos reais armazenados no Storage. A área não altera vídeos de produtos.</p></div><AdminFileUpload bucket={bucket} folder="admin/videos" kind="video" onUploaded={({ file }) => { setMessage(`${file.name} enviado com sucesso.`); void load(); }} onError={setError} />{error && <p role="alert" className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{message && <p role="status" className="rounded-lg border border-primary/30 bg-primary/5 p-3 text-sm text-primary">{message}</p>}{loading ? <p className="rounded-lg border border-border p-8 text-center text-sm text-muted-foreground">Carregando vídeos...</p> : videos.length === 0 ? <div className="rounded-lg border border-dashed border-border p-8 text-center"><Video className="mx-auto text-muted-foreground" size={28} /><h3 className="mt-3 font-medium">Nenhum vídeo encontrado</h3><p className="mt-1 text-sm text-muted-foreground">Envie um vídeo real para disponibilizá-lo nesta galeria.</p></div> : <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{videos.map((video) => <article key={video.path} className="overflow-hidden rounded-lg border border-border bg-background"><video src={video.url} controls preload="metadata" className="aspect-video w-full bg-muted" aria-label={`Prévia de ${video.name}`} /><div className="space-y-3 p-3"><div><p className="truncate text-sm font-medium" title={video.name}>{video.name}</p><p className="text-xs text-muted-foreground">{size(video.size)}{video.createdAt ? ` · ${new Date(video.createdAt).toLocaleDateString("pt-BR")}` : ""}</p><span className="mt-1 inline-flex rounded-full border border-primary/30 px-2 py-1 text-xs text-primary">Disponível</span></div><div className="flex flex-wrap gap-2"><a href={video.url} target="_blank" rel="noreferrer" className="rounded-md border border-border px-3 py-2 text-xs font-medium hover:bg-muted">Visualizar</a><button type="button" onClick={() => setMessage("Este vídeo está disponível no Storage para associação em conteúdos compatíveis.")} className="rounded-md border border-primary/30 px-3 py-2 text-xs font-medium text-primary hover:bg-muted">Editar/Usar</button><button type="button" onClick={() => void remove(video)} className="rounded-md border border-destructive/40 px-3 py-2 text-xs font-medium text-destructive hover:bg-destructive/10">Excluir</button></div></div></article>)}</div>}</section>;
}

function TextAppearanceEditor() {
  const [form, setForm] = useState<TextAppearance>(defaultTextAppearance);
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { void (async () => { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; setForm({ ...defaultTextAppearance, ...(appearance.texts as Partial<TextAppearance> | undefined) }); setLoading(false); })(); }, []);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!supabase) return; try { setSaving(true); setMessage(""); const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) throw error; const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, texts: form } }); if (result.error) throw result.error; setMessage("Configurações salvas no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  return <section className="rounded-xl border border-border bg-card p-5"><div className="mb-5"><h2 className="text-xl font-semibold">Textos da Home</h2><p className="mt-1 text-sm text-muted-foreground">Ajuste título e frase do banner. As alterações são aplicadas na Home após salvar.</p></div><form onSubmit={submit} className="grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando configurações...</p> : <><label className="text-sm">Título do Hero<input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Frase do Hero<textarea value={form.phrase} onChange={(e) => setForm({ ...form, phrase: e.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><label className="text-sm">Fonte do título<select value={form.titleFont} onChange={(e) => setForm({ ...form, titleFont: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option>Playfair Display</option><option>Montserrat</option><option>Syncopate</option></select></label><label className="text-sm">Tamanho do título<input value={form.titleSize} onChange={(e) => setForm({ ...form, titleSize: e.target.value })} placeholder="Ex.: clamp(3rem, 8vw, 7rem)" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Cor do título<input value={form.titleColor} onChange={(e) => setForm({ ...form, titleColor: e.target.value })} placeholder="Ex.: var(--foreground)" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Fonte da frase<select value={form.phraseFont} onChange={(e) => setForm({ ...form, phraseFont: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option>Montserrat</option><option>Playfair Display</option><option>Syncopate</option></select></label><label className="text-sm">Tamanho da frase<input value={form.phraseSize} onChange={(e) => setForm({ ...form, phraseSize: e.target.value })} placeholder="Ex.: 1rem" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Cor da frase<input value={form.phraseColor} onChange={(e) => setForm({ ...form, phraseColor: e.target.value })} placeholder="Ex.: var(--foreground)" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Largura dos textos<input value={form.textWidth} onChange={(e) => setForm({ ...form, textWidth: e.target.value })} placeholder="Ex.: 32rem" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Formatação<select value={form.textFormat} onChange={(e) => setForm({ ...form, textFormat: e.target.value as TextAppearance["textFormat"] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="normal">Normal</option><option value="uppercase">Maiúsculas</option><option value="italic">Itálico</option></select></label><label className="text-sm">Eyebrow da Home<input value={form.heroEyebrow} onChange={(e) => setForm({ ...form, heroEyebrow: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">CTA principal<input value={form.primaryCta} onChange={(e) => setForm({ ...form, primaryCta: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Link do CTA principal<input value={form.primaryCtaUrl} onChange={(e) => setForm({ ...form, primaryCtaUrl: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">CTA secundário<input value={form.secondaryCta} onChange={(e) => setForm({ ...form, secondaryCta: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Link do CTA secundário<input value={form.secondaryCtaUrl} onChange={(e) => setForm({ ...form, secondaryCtaUrl: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Eyebrow das seções<input value={form.sectionEyebrow} onChange={(e) => setForm({ ...form, sectionEyebrow: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Destaque do aviso de frete<input value={form.shippingHighlight} onChange={(e) => setForm({ ...form, shippingHighlight: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Texto do aviso de frete<input value={form.shippingText} onChange={(e) => setForm({ ...form, shippingText: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar configurações"}</button></div></>}</form>{message && <p className="mt-4 rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}</section>;
}

function BannersEditor() {
  const empty = { image_url: "", title: "", text: "", link_url: "", sort_order: 0, active: true };
  const [rows, setRows] = useState<Banner[]>([]); const [form, setForm] = useState(empty); const [editing, setEditing] = useState<string | undefined>(); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [rotationSeconds, setRotationSeconds] = useState(3); const [savingRotation, setSavingRotation] = useState(false);
  async function load() { try { setLoading(true); const [banners, rotation] = await Promise.all([listAdminBanners(), getBannerRotationSeconds()]); setRows(banners); setRotationSeconds(rotation); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os banners."); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  async function saveRotation() { const value = Number.isFinite(rotationSeconds) ? Math.max(1, Math.round(rotationSeconds)) : 3; setRotationSeconds(value); try { setSavingRotation(true); setError(""); await saveBannerRotationSeconds(value); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar o intervalo."); } finally { setSavingRotation(false); } }
  async function submit(event: React.FormEvent) { event.preventDefault(); try { setSaving(true); await saveAdminBanner({ id: editing, ...form, sort_order: Number(form.sort_order) }); setForm(empty); setEditing(undefined); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível salvar o banner."); } finally { setSaving(false); } }
  async function remove(id: string) { if (!window.confirm("Excluir este banner?")) return; try { await deleteAdminBanner(id); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível excluir o banner."); } }
  return <div className="space-y-6"><section className="rounded-xl border border-border bg-card p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="text-xl font-semibold">Personalização da Home</h2><p className="mt-1 max-w-2xl text-sm text-muted-foreground">Edite os textos publicados em cada banner. A Home usa a ordem e a frase de cada registro ativo.</p></div><label className="flex items-center gap-2 text-xs text-primary">Rotação (segundos)<input type="number" min="1" step="1" value={rotationSeconds} onChange={(event) => setRotationSeconds(Number(event.target.value))} onBlur={() => void saveRotation()} onKeyDown={(event) => { if (event.key === "Enter") void saveRotation(); }} className="h-8 w-20 rounded-lg border border-primary/40 bg-background px-2 text-foreground" />{savingRotation ? "Salvando..." : ""}</label></div><p className="mt-4 text-xs text-muted-foreground">O intervalo padrão é de 3 segundos. Altere o valor acima para definir o tempo de rotação automática na Home.</p></section><form onSubmit={submit} className="grid gap-4 rounded-xl border border-border bg-card p-4 shadow-sm sm:p-5 md:grid-cols-2"><label className="text-sm">Título principal<input aria-label="Título principal do banner" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><div className="rounded-lg border border-border bg-background p-3 md:col-span-2"><p className="text-sm font-medium">Imagem do banner</p><AdminFileUpload kind="image" folder="banners" onUploaded={({ url }) => setForm((current) => ({ ...current, image_url: url }))} onError={setError} />{form.image_url && <div className="mt-3 overflow-hidden rounded-lg border border-border"><img src={form.image_url} alt="Prévia da imagem do banner" className="max-h-56 w-full object-cover" /><p className="border-t border-border px-3 py-2 text-xs text-muted-foreground">Imagem selecionada para este banner. Envie outra para trocar.</p></div>}</div><label className="text-sm md:col-span-2">Frase usada neste banner<textarea aria-label="Frase usada neste banner" rows={3} value={form.text} onChange={(e) => setForm({ ...form, text: e.target.value })} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><label className="text-sm">Link da ação<input value={form.link_url} onChange={(e) => setForm({ ...form, link_url: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Ordem de exibição<input type="number" min="0" value={form.sort_order} onChange={(e) => setForm({ ...form, sort_order: Number(e.target.value) })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Banner ativo</label><div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editing ? "Atualizar banner" : "Adicionar banner"}</button></div></form>{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando banners...</p> : rows.length === 0 ? <p className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Nenhum banner cadastrado.</p> : rows.map((banner) => <article key={banner.id} className="overflow-hidden rounded-xl border border-border bg-card"><img src={banner.image_url || ""} alt={banner.title || "Banner da Home"} className="aspect-[16/7] w-full object-cover" /><div className="space-y-3 p-4"><div className="flex items-center justify-between gap-3"><h3 className="font-medium">{banner.title || "Sem título"}</h3><span className="text-xs text-muted-foreground">{banner.active ? "Ativo" : "Inativo"}</span></div><p className="text-sm text-muted-foreground">{banner.text || "Sem frase definida"}</p><div className="flex flex-wrap items-center gap-2 border-t border-border pt-3 text-sm"><button type="button" onClick={() => void (async () => { try { await saveAdminBanner({ id: banner.id, image_url: banner.image_url, title: banner.title, text: banner.text, link_url: banner.link_url, sort_order: banner.sort_order, active: !banner.active }); await load(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível alterar o status do banner."); } })()} className="text-primary hover:underline">{banner.active ? "Desativar" : "Ativar"}</button><button type="button" onClick={() => { setEditing(banner.id); setForm({ image_url: banner.image_url || "", title: banner.title || "", text: banner.text || "", link_url: banner.link_url || "", sort_order: banner.sort_order, active: banner.active }); }} className="text-primary hover:underline">Editar</button><button type="button" onClick={() => void remove(banner.id)} className="text-destructive hover:underline">Excluir</button></div></div></article>)}</div></div>;
}

function ProductsArea({ area, onAreaChange }: { area: "Produtos" | "Categorias" | "Imagens" | "Variantes" | "Preços" | "Promoções"; onAreaChange: (area: "Produtos" | "Categorias" | "Imagens" | "Variantes" | "Preços" | "Promoções") => void }) {
  const areas = ["Produtos", "Categorias", "Variantes", "Promoções"] as const;

  function renderArea() {
    switch (area) {
      case "Categorias": return <CategoriesManager />;
      case "Variantes": return <ProductVariantsManager />;
      case "Imagens": return <ProductImagesManager />;
      case "Preços": return <ProductPricesManager />;
      case "Promoções": return <ProductPromotionsManager />;
      case "Produtos": return <AdminProductsManager onCreateCategory={() => onAreaChange("Categorias")} />;
    }
  }

  return <div className="mt-8 space-y-6">
    <nav aria-label="Navegação de Produtos" className="flex flex-wrap gap-2 border-b border-border">
      {areas.map((item) => <button key={item} type="button" onClick={() => onAreaChange(item)} aria-current={area === item ? "page" : undefined} className={`border-b-2 px-3 py-2 text-sm transition ${area === item ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{item}</button>)}
    </nav>
    <div key={area}>{renderArea()}</div>
  </div>;
}

function AdminProductsManager({ onCreateCategory }: { onCreateCategory: () => void }) {
  const emptyForm = { name: "", slug: "", description: "", price: "", category_id: "", active: true, featured: false, published: true, sku: "", stock_quantity: "0", image: "", images: "", video: "", colors: "", sizes: "", variantStock: {} as Record<string, string> };
  const [products, setProducts] = useState<AdminProduct[]>([]);
  const [categories, setCategories] = useState<AdminCategory[]>([]);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState<string | undefined>();
  const [showForm, setShowForm] = useState(false);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [status, setStatus] = useState("all");
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [additionalUploadKey, setAdditionalUploadKey] = useState(0);
  const [error, setError] = useState("");
  const pageSize = 10;
  const fabricColors = ["Preto", "Branco", "Off-white", "Bege", "Marrom", "Caramelo", "Cinza", "Azul-marinho", "Azul", "Verde", "Rosa", "Vermelho"];
  const sizeOptions = ["PP", "P", "M", "G", "GG", "XG"];

  async function load() {
    try { setLoading(true); setError(""); const [productRows, categoryRows] = await Promise.all([listAdminProducts(), listAdminCategories()]); setProducts(productRows); setCategories(categoryRows); }
    catch (err) { setError(describeSupabaseError(err, "Não foi possível carregar os produtos.")); }
    finally { setLoading(false); }
  }
  useEffect(() => { void load(); }, []);
  const filtered = products.filter((product) => {
    const matchesQuery = `${product.name} ${product.slug}`.toLowerCase().includes(query.toLowerCase());
    return matchesQuery && (category === "all" || product.category_id === category) && (status === "all" || (status === "active" ? product.active : !product.active));
  });
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const visible = filtered.slice((page - 1) * pageSize, page * pageSize);
  const primaryImage = (product: AdminProduct) => product.product_images.find((image) => image.is_primary) ?? product.product_images[0];
  const categoryName = (id: string | null) => categories.find((item) => item.id === id)?.name || "Sem categoria";
  function startNew() { setEditingId(undefined); setForm(emptyForm); setShowForm(true); }
  function edit(product: AdminProduct) { const image = primaryImage(product); setEditingId(product.id); setShowForm(true); setForm({ ...emptyForm, name: product.name, slug: product.slug, description: product.description || "", price: String(product.price), category_id: product.category_id || "", active: product.active, featured: product.featured, published: product.published, video: product.video_url || "", sku: product.product_variants[0]?.sku || "", stock_quantity: String(product.product_variants[0]?.stock_quantity ?? 0), image: image?.image_url || "", images: product.product_images.map((item) => item.image_url).join("\n"), colors: [...new Set(product.product_variants.map((item) => item.color).filter(Boolean))].join(", "), sizes: [...new Set(product.product_variants.map((item) => item.size).filter(Boolean))].join(", "), variantStock: Object.fromEntries(product.product_variants.map((item) => [`${item.color ?? ""}::${item.size ?? ""}`, String(item.stock_quantity)])) }); }
  async function submit(event: React.FormEvent) { event.preventDefault(); const sizes = form.sizes.split(",").map((item) => item.trim()).filter(Boolean); const colors = form.colors.split(",").map((item) => item.trim()).filter(Boolean); const quantitiesMissing = sizes.some((size) => (colors.length ? colors : [""]).some((color) => form.variantStock[`${color}::${size}`] === undefined || form.variantStock[`${color}::${size}`] === "")); if (!form.name.trim() || !form.slug.trim() || quantitiesMissing) { setError(quantitiesMissing ? "Informe o estoque de todas as combinações selecionadas." : "Preencha nome e slug."); return; } try { setSaving(true); setError(""); const normalizedSlug = (form.slug.trim() || form.name.trim()).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""); const normalizedPrice = Number(form.price.replace(/[^0-9,]/g, "").replace(/\./g, "").replace(",", ".")) || 0; const savedProductId = await saveAdminProduct({ id: editingId, name: form.name.trim(), slug: normalizedSlug, description: form.description, price: normalizedPrice, category_id: form.category_id || null, active: form.active, featured: form.featured, published: form.published, video_url: form.video.trim() || null, sizes, colors, sku: form.sku.trim(), stock_quantity: Number(form.stock_quantity), images: [...new Set(`${form.image}\n${form.images}`.split("\n").map((item) => item.trim()).filter(Boolean))], primaryImage: 0, variantStock: Object.fromEntries(Object.entries(form.variantStock).map(([key, value]) => [key, Number(value)])) }); setAdditionalUploadKey((value) => value + 1); setForm(emptyForm); setEditingId(undefined); setShowForm(false); await load(); } catch (err) { setError(describeSupabaseError(err, /duplicate|unique/i.test(err instanceof Error ? err.message : "") ? "Já existe um produto com este slug. Altere o slug e tente novamente." : "Não foi possível salvar o produto.")); } finally { setSaving(false); } }
  async function remove(product: AdminProduct) { if (!window.confirm(`Excluir o produto ${product.name}? Esta ação não pode ser desfeita.`)) return; try { setError(""); await deleteAdminProduct(product.id); await load(); } catch (err) { setError(describeSupabaseError(err, "Não foi possível excluir o produto.")); } }
  return <div className="space-y-6">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-sm text-muted-foreground">Catálogo real da loja</p><h2 className="mt-1 text-2xl font-semibold">Produtos</h2></div><button type="button" onClick={startNew} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground transition hover:opacity-90">Adicionar produto</button></div>
    {showForm ? <form onSubmit={submit} className="grid gap-4 rounded-xl border border-primary/40 bg-card p-5 md:grid-cols-2"><h3 className="text-xl font-semibold md:col-span-2">{editingId ? "Editar produto" : "Novo produto"}</h3><label className="text-sm">Nome<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Slug<input value={form.slug} onChange={(e) => setForm({ ...form, slug: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /><span className="mt-1 block text-xs text-muted-foreground">Identificador interno do produto.</span></label><label className="text-sm">Preço (R$)<input required inputMode="numeric" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value.replace(/\D/g, "").replace(/(\d)(\d{2})$/, "$1,$2") })} placeholder="0,00" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Categoria<div className="mt-2 flex gap-2"><select value={form.category_id} onChange={(e) => setForm({ ...form, category_id: e.target.value })} className="h-10 min-w-0 flex-1 rounded-lg border border-input bg-background px-3"><option value="">Sem categoria</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><button type="button" aria-label="Criar categoria" onClick={() => { onCreateCategory(); setError("Crie a categoria na aba Categorias e depois retorne ao produto."); }} className="h-10 w-10 rounded-lg border border-primary text-lg text-primary hover:bg-primary hover:text-primary-foreground">+</button></div></label><div className="space-y-3 md:col-span-2"><p className="text-sm font-medium">Imagem principal <span className="text-xs font-normal text-muted-foreground">(até 20 MB)</span></p><AdminFileUpload kind="image" folder="products" onUploaded={({ url }) => setForm((current) => ({ ...current, image: url }))} onError={setError} />{form.image && <div className="relative w-fit"><img src={form.image} alt="Prévia da imagem principal" className="h-32 w-24 rounded-lg border border-border object-cover" /><button type="button" onClick={() => setForm({ ...form, image: "" })} className="absolute -right-2 -top-2 rounded-full bg-destructive px-2 py-1 text-xs text-destructive-foreground">×</button></div>}</div><p className="text-xs text-muted-foreground md:col-span-2">As imagens são gravadas em product_images e as combinações em product_variants.</p><div className="space-y-3 md:col-span-2"><p className="text-sm font-medium">Imagens adicionais ou vídeo <span className="text-xs font-normal text-muted-foreground">(imagens até 20 MB)</span></p><p className="text-xs text-muted-foreground">Envie cada imagem pelo botão de upload. Não é necessário informar URL.</p><AdminFileUpload key={additionalUploadKey} kind="all" folder="products" onUploaded={({ url, file }) => setForm((current) => file.type.startsWith("video/") ? ({ ...current, video: url }) : ({ ...current, images: [...current.images.split("\n").filter(Boolean), url].join("\n") }))} onError={setError} /><div className="grid grid-cols-4 gap-2">{form.images.split("\n").filter(Boolean).map((url) => <div key={url} className="relative"><img src={url} alt="Imagem adicional do produto" className="aspect-square rounded-lg border border-border object-cover" /><button type="button" onClick={() => setForm({ ...form, images: form.images.split("\n").filter((item) => item && item !== url).join("\n") })} className="absolute -right-1 -top-1 rounded-full bg-destructive px-1.5 text-xs text-destructive-foreground">×</button></div>)}</div></div><div className="space-y-3 md:col-span-2"><p className="text-sm font-medium">Vídeo do produto</p><AdminFileUpload kind="video" folder="products" onUploaded={({ url }) => setForm((current) => ({ ...current, video: url }))} onError={setError} />{form.video && <p className="text-xs text-primary">Vídeo selecionado.</p>}</div><fieldset className="space-y-2 text-sm"><legend>Cor</legend><div className="flex flex-wrap gap-2">{fabricColors.map((color) => { const selected = form.colors.split(",").map((item) => item.trim()).filter(Boolean).includes(color); const swatches: Record<string, string> = { Preto: "#111111", Branco: "#ffffff", "Off-white": "#f4efe6", Bege: "#c9a77a", Marrom: "#6b4226", Caramelo: "#b9783f", Cinza: "#888888", "Azul-marinho": "#1f315f", Azul: "#3b82f6", Verde: "#22c55e", Rosa: "#ec4899", Vermelho: "#ef4444" }; return <button type="button" key={color} onClick={() => setForm({ ...form, colors: selected ? form.colors.split(",").map((item) => item.trim()).filter((item) => item !== color).join(", ") : [...form.colors.split(",").map((item) => item.trim()).filter(Boolean), color].join(", ") })} className={`inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs ${selected ? "border-primary bg-primary text-primary-foreground" : "border-border"}`}><span className="h-3 w-3 rounded-full border border-border" style={{ backgroundColor: swatches[color] }} aria-hidden="true" />{color}</button>; })}</div><input aria-label="Cor manual" placeholder="Outra cor manual" value={form.colors.split(",").find((color) => !fabricColors.includes(color.trim()))?.trim() ?? ""} onChange={(e) => { const selected = form.colors.split(",").map((item) => item.trim()).filter((item) => fabricColors.includes(item)); setForm({ ...form, colors: [...selected, e.target.value.trim()].filter(Boolean).join(", ") }); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></fieldset><fieldset className="space-y-2 text-sm"><legend>Tamanhos</legend><div className="flex flex-wrap gap-2">{sizeOptions.map((size) => { const selected = form.sizes.split(",").map((item) => item.trim()).includes(size); return <button type="button" key={size} onClick={() => setForm({ ...form, sizes: selected ? form.sizes.split(",").map((item) => item.trim()).filter((item) => item !== size).join(", ") : [...form.sizes.split(",").map((item) => item.trim()).filter(Boolean), size].join(", ") })} className={`rounded-lg border px-4 py-2 text-sm ${selected ? "border-primary bg-primary text-primary-foreground" : "border-border"}`}>{size}</button>; })}</div></fieldset><div className="grid gap-3 md:col-span-2 md:grid-cols-3">{form.sizes.split(",").map((size) => size.trim()).filter(Boolean).flatMap((size) => { const colors = form.colors.split(",").map((color) => color.trim()).filter(Boolean); return (colors.length ? colors : [""]).map((color) => { const key = `${color}::${size}`; return <label key={key} className="text-sm">Estoque · {color || "Única"} / {size}<input type="number" min="0" value={form.variantStock[key] ?? form.stock_quantity} onChange={(event) => setForm({ ...form, variantStock: { ...form.variantStock, [key]: event.target.value } })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label>; }); })}</div><label className="text-sm md:col-span-2">Descrição<textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /></label><div className="flex flex-wrap gap-4 text-sm md:col-span-2"><label className="flex items-center gap-2"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Ativo</label><label className="flex items-center gap-2"><input type="checkbox" checked={form.published} onChange={(e) => setForm({ ...form, published: e.target.checked })} />Publicado</label><label className="flex items-center gap-2"><input type="checkbox" checked={form.featured} onChange={(e) => setForm({ ...form, featured: e.target.checked })} />Destaque</label></div><div className="flex gap-3 md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editingId ? "Atualizar produto" : "Salvar produto"}</button><button type="button" onClick={() => { setShowForm(false); setEditingId(undefined); setForm(emptyForm); }} className="rounded-lg border border-border px-4 py-2 text-sm">Cancelar</button></div></form> : null}
    <div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_12rem_10rem]"><label className="text-sm font-medium">Buscar produto<input aria-label="Buscar produto" value={query} onChange={(e) => { setQuery(e.target.value); setPage(1); }} placeholder="Nome ou slug" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Categoria<select value={category} onChange={(e) => { setCategory(e.target.value); setPage(1); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todas</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="text-sm font-medium">Status<select value={status} onChange={(e) => { setStatus(e.target.value); setPage(1); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select></label></div>
    {error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}
    <div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[820px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Produto</th><th className="p-4">Categoria</th><th className="p-4">Preço</th><th className="p-4">Estoque</th><th className="p-4">Status</th><th className="p-4">Ações</th></tr></thead><tbody>{loading ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Carregando produtos...</td></tr> : visible.length === 0 ? <tr><td colSpan={6} className="p-8 text-center text-muted-foreground">Nenhum produto encontrado.</td></tr> : visible.map((product) => { const image = primaryImage(product); const stock = product.product_variants.reduce((sum, variant) => sum + variant.stock_quantity, 0); return <tr key={product.id} tabIndex={0} role="button" onClick={() => edit(product)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") edit(product); }} className="cursor-pointer border-b border-border transition hover:bg-muted/50 focus-visible:bg-muted/50 last:border-0"><td className="p-4"><div className="flex items-center gap-3"><div className="h-14 w-12 overflow-hidden rounded-lg border border-border bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || product.name} className="h-full w-full object-cover" /> : null}</div><div><p className="font-medium">{product.name}</p><p className="text-xs text-muted-foreground">{product.slug}</p></div></div></td><td className="p-4 text-muted-foreground">{categoryName(product.category_id)}</td><td className="p-4">R$ {product.price.toFixed(2)}</td><td className="p-4">{stock}</td><td className="p-4">{product.active ? "Ativo" : "Inativo"}</td><td className="p-4"><button type="button" onClick={(event) => { event.stopPropagation(); edit(product); }} className="mr-3 text-primary hover:underline">Editar</button><button type="button" onClick={(event) => { event.stopPropagation(); void remove(product); }} className="text-destructive hover:underline">Excluir</button></td></tr>; })}</tbody></table></div>
    <div className="flex items-center justify-between gap-4 text-sm text-muted-foreground"><span>{filtered.length} produto(s) · Página {page} de {totalPages}</span><div className="flex gap-2"><button type="button" aria-label="Página anterior" disabled={page === 1} onClick={() => setPage((current) => current - 1)} className="rounded-lg border border-border px-3 py-2 text-lg leading-none transition hover:border-primary hover:text-primary disabled:opacity-40">&lt;</button><button type="button" aria-label="Próxima página" disabled={page >= totalPages} onClick={() => setPage((current) => current + 1)} className="rounded-lg border border-border px-3 py-2 text-lg leading-none transition hover:border-primary hover:text-primary disabled:opacity-40">&gt;</button></div></div>
  </div>;
}

function OrdersManager({ initialOrderId }: { initialOrderId?: string | null }) {
  const [orders, setOrders] = useState<any[]>([]);
  const [selected, setSelected] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [savingStatus, setSavingStatus] = useState(false);
  useEffect(() => { void (async () => { try { const rows = await listAdminOrders(); setOrders(rows); if (initialOrderId) setSelected(rows.find((order) => order.id === initialOrderId) ?? null); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os pedidos."); } finally { setLoading(false); } })(); }, [initialOrderId]);
  async function openOrder(id: string) { try { setError(""); const order = await getAdminOrder(id); setSelected(order); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os detalhes."); } }
  async function changeStatus(status: string) { if (!selected || !status) return; try { setSavingStatus(true); await updateAdminOrderStatus(selected.id, status); const refreshed = await getAdminOrder(selected.id); setSelected(refreshed); setOrders((current) => current.map((order) => order.id === refreshed.id ? { ...order, status: refreshed.status } : order)); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível atualizar o status."); } finally { setSavingStatus(false); } }
  const customer = (order: any) => order.shipping_address?.full_name || order.customer_name || order.customer_email || "Cliente não identificado";
  const payment = (order: any) => order.payment_status || order.payment_method || "—";
  const address = (order: any) => { const value = order.shipping_address; if (!value) return "Não informado"; return [value.address, value.cep, value.city, value.state].filter(Boolean).join(" · ") || "Não informado"; };
  const shipment = (order: any) => order.shipments?.[0];
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}{selected && <section className="rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Detalhes do pedido</p><h2 className="mt-2 text-2xl font-semibold">{selected.order_number || selected.number}</h2></div><button type="button" onClick={() => setSelected(null)} className="text-sm text-muted-foreground hover:text-foreground">Fechar</button></div><div className="mt-5 grid gap-3 text-sm md:grid-cols-2"><p><span className="text-muted-foreground">Cliente:</span> {customer(selected)}</p><p><span className="text-muted-foreground">Endereço:</span> {address(selected)}</p><p><span className="text-muted-foreground">Pagamento:</span> {payment(selected)}</p><p><span className="text-muted-foreground">Total:</span> R$ {Number(selected.total || 0).toFixed(2)}</p><label><span className="text-muted-foreground">Status:</span><select value={selected.status || ""} disabled={savingStatus} onChange={(event) => void changeStatus(event.target.value)} className="ml-2 rounded-lg border border-input bg-background px-2 py-1"><option value="">Selecione</option>{["pending", "preparing", "shipped", "delivered", "cancelled"].map((status) => <option key={status} value={status}>{status}</option>)}</select></label><p><span className="text-muted-foreground">Entrega:</span> {shipment(selected)?.status || "Em preparação"}{shipment(selected)?.tracking_code ? ` · ${shipment(selected).tracking_code}` : ""}</p></div><div className="mt-5 border-t border-border pt-4"><h3 className="font-medium">Itens</h3>{(selected.order_items || []).map((item: any) => <p key={item.id} className="mt-2 text-sm text-muted-foreground">{item.product_name || item.name || "Produto"} · quantidade: {item.quantity} · R$ {Number(item.total || item.unit_price || item.price || 0).toFixed(2)}</p>)}</div></section>}<div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full text-left text-sm"><thead className="border-b border-border text-muted-foreground"><tr><th className="p-4">Número do pedido</th><th className="p-4">Cliente</th><th className="p-4">Data</th><th className="p-4">Status</th><th className="p-4">Pagamento</th><th className="p-4">Total</th><th className="p-4">Ação</th></tr></thead><tbody>{loading ? <tr><td colSpan={7} className="p-8 text-center text-muted-foreground">Carregando pedidos...</td></tr> : orders.length === 0 ? <tr><td colSpan={7} className="p-8 text-center text-muted-foreground">Nenhum pedido encontrado.</td></tr> : orders.map((order) => <tr key={order.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{order.order_number || order.number || order.id}</td><td className="p-4">{customer(order)}</td><td className="p-4 text-muted-foreground">{order.created_at ? new Date(order.created_at).toLocaleString("pt-BR") : "—"}</td><td className="p-4">{order.status || "—"}</td><td className="p-4">{payment(order)}</td><td className="p-4">R$ {Number(order.total || 0).toFixed(2)}</td><td className="p-4"><button type="button" onClick={() => void openOrder(order.id)} className="text-primary hover:underline">Ver detalhes</button></td></tr>)}</tbody></table></div></div>;
}

function OrderDetails({ order, onClose }: { order: any; onClose: () => void }) {
  const itemImage = (item: any) => item.product?.product_images?.find((image: any) => image.is_primary) ?? item.product?.product_images?.[0];
  const address = order.shipping_address ?? {};
  const payment = order.payments?.[0] ?? order.payment ?? {};
  const shipment = order.shipments?.[0] ?? order.shipment ?? {};
  const subtotal = Number(order.subtotal ?? order.order_items?.reduce((sum: number, item: any) => sum + Number(item.subtotal ?? item.total ?? Number(item.unit_price ?? item.price ?? 0) * Number(item.quantity ?? 0)), 0) ?? 0);
  const freight = Number(order.shipping_total ?? order.shipping ?? order.shipping_cost ?? 0);
  return <section className="space-y-6 rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs uppercase tracking-[0.2em] text-primary">Detalhes do pedido</p><h2 className="mt-2 text-2xl font-semibold">{order.order_number || order.id}</h2><p className="text-sm text-muted-foreground">{order.created_at ? new Date(order.created_at).toLocaleString("pt-BR") : "Data não informada"}</p></div><button type="button" onClick={onClose} className="text-sm text-muted-foreground hover:text-foreground">Fechar</button></div>
    <div className="grid gap-4 md:grid-cols-2"><div><h3 className="font-medium">Cliente</h3><p className="mt-2 text-sm">{order.customer_name || address.full_name || "Nome não informado"}</p><p className="text-sm text-muted-foreground">{order.customer_email || address.email || "E-mail não informado"}</p><p className="text-sm text-muted-foreground">{address.phone || order.customer_phone || "Telefone não informado"}</p><p className="mt-2 text-sm text-muted-foreground">{[address.address, address.cep, address.city, address.state].filter(Boolean).join(" · ") || "Endereço não informado"}</p></div><div><h3 className="font-medium">Pagamento</h3><p className="mt-2 text-sm">Status: {payment.status || payment.payment_status || order.payment_status || "Não informado"}</p><p className="text-sm">Valor: R$ {Number(payment.amount ?? payment.transaction_amount ?? order.total ?? 0).toFixed(2).replace(".", ",")}</p><p className="text-sm text-muted-foreground">Referência: {payment.reference || payment.external_reference || payment.preference_id || payment.id || "Não disponível"}</p></div></div>
    <div><h3 className="font-medium">Produtos</h3><div className="mt-3 space-y-3">{(order.order_items ?? []).map((item: any, index: number) => { const image = itemImage(item); const unit = Number(item.unit_price ?? item.price ?? 0); const quantity = Number(item.quantity ?? 0); return <article key={item.id || index} className="flex gap-3 border-b border-border pb-3"><div className="h-16 w-12 shrink-0 overflow-hidden rounded-lg bg-muted">{image ? <img src={image.image_url} alt={image.alt_text || item.product?.name || item.product_name || "Produto"} className="h-full w-full object-cover" /> : null}</div><div className="min-w-0 text-sm"><p className="font-medium">{item.product?.name || item.product_name || item.name || "Produto não identificado"}</p><p className="text-muted-foreground">Cor: {item.variant?.color || item.color || "—"} · Tamanho: {item.variant?.size || item.size || "—"} · SKU: {item.variant?.sku || item.sku || "—"}</p><p className="text-muted-foreground">Quantidade: {quantity} · Unitário: R$ {unit.toFixed(2).replace(".", ",")} · Subtotal: R$ {(Number(item.subtotal ?? item.total ?? unit * quantity)).toFixed(2).replace(".", ",")}</p></div></article>; })}</div></div>
    <div className="grid gap-3 border-t border-border pt-4 text-sm md:grid-cols-3"><p>Subtotal: R$ {subtotal.toFixed(2).replace(".", ",")}</p><p>Frete: R$ {freight.toFixed(2).replace(".", ",")}</p><p className="font-semibold">Total: R$ {Number(order.total ?? subtotal + freight).toFixed(2).replace(".", ",")}</p></div>
    <div className="grid gap-4 md:grid-cols-2"><div><h3 className="font-medium">Entrega</h3><p className="mt-2 text-sm">Status: {shipment.status || order.shipping_status || "Não informado"}</p><p className="text-sm">Transportadora: {shipment.carrier || shipment.service || "Não informada"}</p><p className="text-sm text-muted-foreground">Rastreio: {shipment.tracking_code || shipment.tracking_number || "Não disponível"}</p></div><div><h3 className="font-medium">Linha do tempo</h3><ol className="mt-2 space-y-2 text-sm"><li>Pedido criado · {order.created_at ? new Date(order.created_at).toLocaleString("pt-BR") : "—"}</li><li>Status atual · {order.status || "Não informado"}</li><li>Pagamento · {payment.status || payment.payment_status || order.payment_status || "Não informado"}</li><li>Transporte · {shipment.status || order.shipping_status || "Não informado"}</li></ol></div></div>
  </section>;
}

function ShipmentsManager() {
  const [rows, setRows] = useState<any[]>([]); const [query, setQuery] = useState(""); const [status, setStatus] = useState("all"); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [selectedOrder, setSelectedOrder] = useState<any | null>(null); const [saving, setSaving] = useState(false); const [form, setForm] = useState({ carrier: "", tracking_code: "", tracking_url: "", status: "pending", order_item_ids: [] as string[] });
  useEffect(() => { void (async () => { try { if (!supabase) throw new Error("Supabase não está configurado."); const [ordersResult, paymentsResult, shipmentsResult] = await Promise.all([supabase.from("orders").select("*, order_items(*)").order("created_at", { ascending: false }), supabase.from("payments").select("*"), supabase.from("shipments").select("*").order("created_at", { ascending: false })]); if (ordersResult.error) throw ordersResult.error; if (paymentsResult.error) throw paymentsResult.error; if (shipmentsResult.error) throw shipmentsResult.error; const paid = new Set((paymentsResult.data ?? []).filter((p: any) => ["approved", "confirmed", "paid", "pago", "aprovado", "confirmado"].includes(String(p.status ?? p.payment_status ?? "").toLowerCase())).map((p: any) => String(p.order_id ?? p.external_reference ?? ""))); const byOrder = new Map<string, any[]>(); (shipmentsResult.data ?? []).forEach((s: any) => { const list = byOrder.get(String(s.order_id)) ?? []; list.push(s); byOrder.set(String(s.order_id), list); }); const loaded = (ordersResult.data ?? []).filter((o: any) => paid.has(String(o.id))).flatMap((order: any) => (byOrder.get(String(order.id)) ?? [null]).map((shipment: any) => ({ order, shipment, count: (byOrder.get(String(order.id)) ?? []).length }))); setRows(loaded); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os envios reais."); } finally { setLoading(false); } })(); }, []);
  const label = (row: any) => row.order.shipping_address?.full_name || row.order.customer_name || row.order.customer_email || "Cliente não identificado";
  const text = (row: any) => `${row.order.order_number || row.order.id} ${label(row)} ${row.shipment?.tracking_code || row.shipment?.tracking_number || ""}`.toLowerCase();
  const statuses = [...new Set(rows.map((row) => row.shipment?.status || "Sem rastreio"))];
  const filtered = rows.filter((row) => text(row).includes(query.toLowerCase()) && (status === "all" || (row.shipment?.status || "Sem rastreio") === status));
  async function saveShipment(event: React.FormEvent) { event.preventDefault(); if (!selectedOrder || !supabase) return; try { setSaving(true); const { error: insertError } = await supabase.from("shipments").insert({ order_id: selectedOrder.id, carrier: form.carrier.trim() || null, tracking_code: form.tracking_code.trim() || null, tracking_url: form.tracking_url.trim() || null, status: form.status, order_item_ids: form.order_item_ids }); if (insertError) throw insertError; setSelectedOrder(null); setForm({ carrier: "", tracking_code: "", tracking_url: "", status: "pending", order_item_ids: [] }); window.location.reload(); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível cadastrar o envio real."); } finally { setSaving(false); } }
  return <div className="mt-8 space-y-6">{selectedOrder && <form onSubmit={saveShipment} className="space-y-4 rounded-xl border border-primary/40 bg-card p-5"><div className="flex items-center justify-between"><div><p className="text-xs uppercase tracking-wider text-primary">Novo rastreio</p><h2 className="text-xl font-semibold">Pedido {selectedOrder.order_number || selectedOrder.id}</h2></div><button type="button" onClick={() => setSelectedOrder(null)} className="text-sm text-muted-foreground">Fechar</button></div><label className="block text-sm">Transportadora<input required value={form.carrier} onChange={(e) => setForm({ ...form, carrier: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="block text-sm">Código de rastreio<input value={form.tracking_code} onChange={(e) => setForm({ ...form, tracking_code: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="block text-sm">URL de rastreamento<input type="url" value={form.tracking_url} onChange={(e) => setForm({ ...form, tracking_url: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="block text-sm">Status<select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="pending">Pendente</option><option value="in_transit">Em trânsito</option><option value="delivered">Entregue</option></select></label><fieldset><legend className="text-sm">Produtos relacionados</legend><div className="mt-2 space-y-2">{(selectedOrder.order_items ?? []).map((item: any) => <label key={item.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={form.order_item_ids.includes(item.id)} onChange={(e) => setForm({ ...form, order_item_ids: e.target.checked ? [...form.order_item_ids, item.id] : form.order_item_ids.filter((id) => id !== item.id) })} />{item.product_name || item.name || "Produto"} · qtd. {item.quantity}</label>)}</div></fieldset><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Cadastrar envio"}</button></form>}{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-[1fr_14rem]"><label className="text-sm font-medium">Buscar pedido, cliente ou código<input aria-label="Buscar envio" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Número, nome ou rastreio" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Status<select aria-label="Filtrar envios por status" value={status} onChange={(e) => setStatus(e.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{statuses.map((item) => <option key={String(item)}>{String(item)}</option>)}</select></label></div><div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Pedido</th><th className="p-4">Cliente</th><th className="p-4">Produtos</th><th className="p-4">Data</th><th className="p-4">Transportadora</th><th className="p-4">Rastreio</th><th className="p-4">Status</th><th className="p-4">Rastreios</th></tr></thead><tbody>{loading ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Carregando envios reais...</td></tr> : filtered.length === 0 ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Nenhum envio encontrado.</td></tr> : filtered.map((row, index) => <tr key={`${row.order.id}-${row.shipment?.id || index}`} className="border-b border-border last:border-0"><td className="p-4 font-medium">{row.order.order_number || row.order.id}</td><td className="p-4">{label(row)}</td><td className="p-4">{(row.order.order_items ?? []).map((item: any) => `${item.product_name || item.name || "Produto"} (${item.quantity || 0})`).join(", ") || "—"}</td><td className="p-4 text-muted-foreground">{new Date(row.shipment?.created_at || row.order.created_at).toLocaleString("pt-BR")}</td><td className="p-4">{row.shipment?.carrier || row.shipment?.service || "—"}</td><td className="p-4">{row.shipment?.tracking_code || row.shipment?.tracking_number || "Ainda não informado"}</td><td className="p-4">{row.shipment?.status || "Sem rastreio"}</td><td className="p-4">{row.count}</td><td className="p-4"><button type="button" onClick={() => { setSelectedOrder(row.order); setForm({ carrier: row.shipment?.carrier || "", tracking_code: "", tracking_url: "", status: "pending", order_item_ids: [] }); }} className="text-primary hover:underline">Adicionar rastreio</button></td></tr>)}</tbody></table></div></div>;
}

function OrdersManagerList({ initialOrderId }: { initialOrderId?: string | null }) {
  const [rows, setRows] = useState<any[]>([]); const [selected, setSelected] = useState<any | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const [query, setQuery] = useState(""); const [period, setPeriod] = useState("all"); const [orderStatus, setOrderStatus] = useState("all"); const [paymentStatus, setPaymentStatus] = useState("all"); const [shippingStatus, setShippingStatus] = useState("all");
  useEffect(() => { void (async () => { try { if (!supabase) throw new Error("Supabase não está configurado."); const [ordersResult, paymentsResult, shipmentsResult] = await Promise.all([supabase.from("orders").select("*, order_items(*)").order("created_at", { ascending: false }), supabase.from("payments").select("*"), supabase.from("shipments").select("*")]); if (ordersResult.error) throw ordersResult.error; if (paymentsResult.error) throw paymentsResult.error; if (shipmentsResult.error) throw shipmentsResult.error; const payments = new Map((paymentsResult.data ?? []).map((item: any) => [String(item.order_id ?? item.external_reference ?? item.order_id_external ?? ""), item])); const shipments = new Map((shipmentsResult.data ?? []).map((item: any) => [String(item.order_id ?? ""), item])); const loaded = (ordersResult.data ?? []).map((order: any) => ({ ...order, payment: payments.get(String(order.id)), shipment: shipments.get(String(order.id)) })); setRows(loaded); if (initialOrderId) setSelected(loaded.find((item) => item.id === initialOrderId) ?? null); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os pedidos."); } finally { setLoading(false); } })(); }, [initialOrderId]);
  const customer = (order: any) => order.shipping_address?.full_name || order.customer_name || order.customer_email || "Cliente não identificado";
  const payment = (order: any) => order.payment?.status || order.payment?.payment_status || order.payment_status || order.payment_method || "—";
  const transport = (order: any) => order.shipment?.status || order.shipping_status || "—";
  const values = (field: string) => [...new Set(rows.map((row) => field === "payment" ? payment(row) : field === "shipping" ? transport(row) : row[field]).filter(Boolean))];
  async function openDetails(id: string) { try { setError(""); setSelected(await getAdminOrder(id)); } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os detalhes do pedido."); } }
  const filtered = rows.filter((order) => { const text = `${order.order_number || order.id} ${customer(order)}`.toLowerCase(); const date = new Date(order.created_at).getTime(); const days = period === "7" ? 7 : period === "30" ? 30 : period === "90" ? 90 : 0; return text.includes(query.toLowerCase()) && (orderStatus === "all" || String(order.status || "").toLowerCase() === orderStatus.toLowerCase()) && (paymentStatus === "all" || payment(order).toLowerCase() === paymentStatus.toLowerCase()) && (shippingStatus === "all" || transport(order).toLowerCase() === shippingStatus.toLowerCase()) && (!days || date >= Date.now() - days * 86400000); });
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-5"><label className="text-sm font-medium md:col-span-2">Buscar pedido ou cliente<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Número ou nome/e-mail" className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm font-medium">Período<select value={period} onChange={(event) => setPeriod(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todo o período</option><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option></select></label><label className="text-sm font-medium">Pedido<select value={orderStatus} onChange={(event) => setOrderStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{values("status").map((item) => <option key={item}>{item}</option>)}</select></label><label className="text-sm font-medium">Pagamento<select value={paymentStatus} onChange={(event) => setPaymentStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{values("payment").map((item) => <option key={item}>{item}</option>)}</select></label><label className="text-sm font-medium">Transporte<select value={shippingStatus} onChange={(event) => setShippingStatus(event.target.value)} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="all">Todos</option>{values("shipping").map((item) => <option key={item}>{item}</option>)}</select></label></div>{selected && <OrderDetails order={selected} onClose={() => setSelected(null)} />}<div className="overflow-x-auto rounded-xl border border-border bg-card"><table className="w-full min-w-[1050px] text-left text-sm"><thead className="border-b border-border text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="p-4">Pedido</th><th className="p-4">Cliente</th><th className="p-4">Data e hora</th><th className="p-4">Valor total</th><th className="p-4">Pagamento</th><th className="p-4">Pedido</th><th className="p-4">Transporte</th><th className="p-4">Ação</th></tr></thead><tbody>{loading ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Carregando pedidos reais...</td></tr> : filtered.length === 0 ? <tr><td colSpan={8} className="p-8 text-center text-muted-foreground">Nenhum pedido encontrado.</td></tr> : filtered.map((order) => <tr key={order.id} className="border-b border-border last:border-0"><td className="p-4 font-medium">{order.order_number || order.id}</td><td className="p-4">{customer(order)}</td><td className="p-4 text-muted-foreground">{new Date(order.created_at).toLocaleString("pt-BR")}</td><td className="p-4">R$ {Number(order.total || 0).toFixed(2).replace(".", ",")}</td><td className="p-4">{payment(order)}</td><td className="p-4">{order.status || "—"}</td><td className="p-4">{transport(order)}</td><td className="p-4"><button type="button" onClick={() => void openDetails(order.id)} className="text-primary hover:underline">Abrir detalhes</button></td></tr>)}</tbody></table></div></div>;
}

